    // SDR-content-brightness floor. Below this the DWM SDR boost crushes all SDR
    // (desktop/taskbar) while HDR content stays bright ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â the "random dimming" symptom.
    // Clamp every save AND re-apply so a stale low value in an old settings file
    // can never re-crush SDR. Max mirrors the SdrSlider Maximum (6.0).
    private const double MinSdrBrightness = 3.0;
    private static double ClampSdr(double v) => Math.Clamp(v, MinSdrBrightness, 6.0);

