    public PopupWindow()
    {
        InitializeComponent();

        LoadLogo();

        // Custom capture-based slider interaction:
        // Click anywhere on track ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ jump to position; hold and drag ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ follows mouse,
        // even outside slider bounds; release ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ commit once.
        BrightnessSlider.PreviewMouseLeftButtonDown += OnBrightnessSliderDown;
        BrightnessSlider.PreviewMouseMove           += OnBrightnessSliderMove;
        BrightnessSlider.PreviewMouseLeftButtonUp   += OnBrightnessSliderUp;
        SdrSlider.PreviewMouseLeftButtonDown        += OnSdrSliderDown;
        SdrSlider.PreviewMouseMove                  += OnSdrSliderMove;
        SdrSlider.PreviewMouseLeftButtonUp          += OnSdrSliderUp;
        DimSlider.PreviewMouseLeftButtonDown        += OnDimSliderDown;
        DimSlider.PreviewMouseMove                  += OnDimSliderMove;
        DimSlider.PreviewMouseLeftButtonUp          += OnDimSliderUp;

        _cardBorders = new Dictionary<string, Border>
        {
            ["Gopher"]  = GopherCard,
            ["Audio"]   = AudioCard,
            ["Display"] = DisplayCard,
            ["Prayer"]  = PrayerCard,
        };
        LayoutCards();

        _suppressSliders = true;
        SdrSlider.Value = AppSettings.Current.SdrBrightness;
        SdrValueLabel.Text = $"{SdrSlider.Value:F1}";
        _suppressSliders = false;

        IsVisibleChanged += OnIsVisibleChanged;

        // Auto-hide timer + interaction cancels (hover or click over the popup).
        _autoHideTimer = new DispatcherTimer { Interval = CommandAutoHideDelay };
        _autoHideTimer.Tick += OnAutoHideTick;
        PopupBorder.MouseEnter += (_, _) => CancelAutoHide();
        PreviewMouseDown       += OnPopupPreviewMouseDown;

        // Re-anchor if the display work area changes (resolution / scaling / taskbar)
        // while the popup is open. This app is system-DPI-aware, so it never receives
        // WM_DPICHANGED ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â DisplaySettingsChanged is the reliable signal here.
        Microsoft.Win32.SystemEvents.DisplaySettingsChanged += OnDisplaySettingsChanged;

        if (Themes.TryGetValue(AppSettings.Current.Theme, out var t))
            ApplyThemePalette(t);

        AttachHelpEvents();

        // Builds the prayer module, or shows the "Set up in Settings" hint if Country/City
        // are unset. Single source of truth for the prayer card (also used after edits).
        ReinitPrayerModule();
    }

    // Loads the embedded app icon into the header logo image, picking a crisp frame for the
    // 48px circular display. Reuses the win32 EmbeddedResource (LogicalName pccontrol.ico),
    // so no separate WPF image asset is needed.
    private void LoadLogo()
    {
        try
        {
            using var s = System.Reflection.Assembly.GetExecutingAssembly()
                .GetManifestResourceStream("pccontrol.ico");
            if (s is null) return;
            var decoder = System.Windows.Media.Imaging.BitmapDecoder.Create(
                s, System.Windows.Media.Imaging.BitmapCreateOptions.None,
                System.Windows.Media.Imaging.BitmapCacheOption.OnLoad);
            var frames = decoder.Frames;
            LogoImage.Source = frames.OrderBy(f => f.PixelWidth).FirstOrDefault(f => f.PixelWidth >= 96)
                               ?? frames[frames.Count - 1];
        }
        catch (Exception ex) { Logger.Log($"LoadLogo: {ex.Message}"); }
    }

