    // Each card click runs the shared Do* action (also used by HandleCommand) then
    // re-activates the window so it keeps focus after the interaction.

    private void OnGopherClick(object sender, MouseButtonEventArgs e)
    {
        if (_editMode) { e.Handled = true; return; }
        e.Handled = true;
        DoToggleGopher();
        Activate();
    }

    private async void OnAudioClick(object sender, MouseButtonEventArgs e)
    {
        if (_editMode) { e.Handled = true; return; }
        e.Handled = true;
        var cfg = AppSettings.Current;
        if (AudioManager.ConfiguredSlots(cfg).Count < 2)
        {
            MessageBox.Show("Open Settings and choose at least two audio devices first.",
                "PC Companion", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }
        await DoSwitchAudio();
        Activate();
    }

    private async void OnHdrClick(object sender, MouseButtonEventArgs e)
    {
        if (_editMode) { e.Handled = true; return; }
        e.Handled = true;
        await DoToggleHdr();
        Activate();
    }

    private async void OnAutoHdrClick(object sender, MouseButtonEventArgs e)
    {
        if (_editMode) { e.Handled = true; return; }
        e.Handled = true;
        await DoToggleAutoHdr();
        Activate();
    }

