    private void DoToggleGopher()
    {
        _actionInProgress = true;
        try   { GopherManager.Toggle(); RefreshState(); }
        catch (Exception ex) { Logger.Log($"ToggleGopher: {ex.Message}"); }
        finally { _actionInProgress = false; }
    }

    private async Task DoSwitchAudio()
    {
        var cfg = AppSettings.Current;
        if (AudioManager.ConfiguredSlots(cfg).Count < 2)
        {
            Logger.Log("DoSwitchAudio: audio devices not configured ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â skipping");
            return;
        }

        _actionInProgress = true;
        AudioBtn.Text = "...";
        try
        {
            await Task.Run(() => AudioManager.SwitchToNext());
            await Task.Delay(150);
            RefreshState();
        }
        catch (Exception ex)
        {
            Logger.Log($"SwitchAudio: {ex.Message}");
            AudioBtn.Text = "Error";
            await Task.Delay(1500);
            RefreshState();
        }
        finally { _actionInProgress = false; }
    }

    private async Task DoToggleHdr()
    {
        _actionInProgress = true;
        try
        {
            SendHdrKeys();
            await Task.Delay(700);

            // If HDR just turned ON, Windows resets the DWM compositor SDR boost to max.
            // Re-apply the saved value so the screen matches the app slider.
            bool hdrNowOn = await Task.Run(() => HdrDetector.IsEnabled());
            if (hdrNowOn && HdrSliderService.IsSupported)
            {
                double saved = ClampSdr(AppSettings.Current.SdrBrightness);
                Logger.Log($"DoToggleHdr: HDR on ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â re-applying saved SDR brightness {saved:F1}");
                await Task.Run(() => HdrSliderService.Set(saved));
            }

            RefreshState();
        }
        catch (Exception ex) { Logger.Log($"ToggleHdr: {ex.Message}"); }
        finally { _actionInProgress = false; }
    }

    private async Task DoToggleAutoHdr()
    {
        // Auto HDR only applies when HDR is on; bail quietly otherwise (the UI button
        // is dimmed in that state, but a command could still arrive).
        _actionInProgress = true;
        try
        {
            bool hdrOn = await Task.Run(() => HdrDetector.IsEnabled());
            if (!hdrOn) return;

            var current = await Task.Run(() => AutoHdrService.GetState());
            if (current == AutoHdrService.State.Unknown) return;

            var error = await Task.Run(() => AutoHdrService.Toggle(current));
            if (error is not null)
                Logger.Log($"DoToggleAutoHdr: {error}");

            RefreshState();
        }
        catch (Exception ex) { Logger.Log($"DoToggleAutoHdr: {ex.Message}"); }
        finally { _actionInProgress = false; }
    }

