    private void LayoutCards()
    {
        var cards = AppSettings.Current.Cards;
        EnsureAllCards(cards);

        int y = CardsTop;
        foreach (var c in cards)
        {
            if (!_cardBorders.TryGetValue(c.Id, out var border)) continue;
            if (!c.Visible) { border.Visibility = Visibility.Collapsed; continue; }
            border.Visibility = Visibility.Visible;
            Canvas.SetTop(border, y);
            int cardH = c.Id == "Display" ? (int)DisplayCard.Height : CardHeights[c.Id];
            y += cardH + 18;
        }

        // Scene buttons (Couch + Morning) share one row between the cards and Settings.
        CouchModeBtn.Visibility   = Visibility.Visible;
        MorningModeBtn.Visibility = Visibility.Visible;
        Canvas.SetTop(CouchModeBtn, y);
        Canvas.SetTop(MorningModeBtn, y);
        y += 34 + 16; // button height + gap

        Canvas.SetTop(SettingsToggleBtn, y);
        CardsCanvas.Height = y + 32; // room for the toggle label + bottom padding
    }

