Æ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬

    public async void RefreshState()
    {
        var res = Application.Current.Resources;

        bool gopherOn = GopherManager.IsRunning;
        GopherStatus.Text       = gopherOn ? "ON"  : "OFF";
        GopherStatus.Foreground = gopherOn ? (Brush)res["GoodBrush"] : (Brush)res["BadBrush"];
        GopherBtn.Text          = gopherOn ? "Turn Off" : "Turn On";

        var cfg = AppSettings.Current;
        var curDev = AudioManager.GetCurrentDefault();
        string cur = curDev.Id;

        // Match the live default to a configured device by ID first, then by normalized
        // friendly name. Endpoint IDs can change (reconnect / driver update), and Couch
        // Mode or an external switch may set a device whose saved ID is stale ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â the plain
        // ID compare would then mislabel the indicator.
        // Only Device 2 needs explicit detection now: Device 1 and "neither configured
        // device" both render as Device 1 (see below), so isDev1 isn't needed.
        // The Audio card cycles through whichever device slots are configured (2 or 3).
        // Slots are matched to the live default by ID first, then normalized friendly name.
        var audioSlots = AudioManager.ConfiguredSlots(cfg);

        // Not set up until at least two devices are chosen. Mirror the Couch/Morning "Setup"
        // state: dim the card, show a hint + tooltip. OnAudioClick/DoSwitchAudio also refuse
        // to run while under-configured, so the card matches what the button will do.
        if (audioSlots.Count < 2)
        {
            AudioStatus.Text       = "Set up in Settings";
            AudioStatus.Foreground = (Brush)res["DimBrush"];
            AudioBtn.Text          = "Setup";
            AudioCard.Opacity      = 0.55;
            AudioCard.ToolTip      = "Set up at least two audio devices in Settings first.";
        }
        else
        {
            AudioCard.Opacity      = 1.0;
            AudioCard.ToolTip      = null;
            // Current slot, treating "none of the configured devices" (e.g. a scene's audio
            // target) as the first slot — matching SwitchToNext so the button stays truthful.
            int curSlot = AudioManager.CurrentSlot(cfg, cur, curDev.Name);
            int curIdx  = curSlot > 0 ? audioSlots.IndexOf(curSlot) : 0;
            if (curIdx < 0) curIdx = 0;
            int shownSlot = audioSlots[curIdx];
            int nextSlot  = audioSlots[(curIdx + 1) % audioSlots.Count];

            // Per-slot accent so the up-to-three devices stay visually distinct.
            AudioStatus.Text       = Short(AudioManager.SlotLabel(cfg, shownSlot));
            AudioStatus.Foreground = (Brush)res[shownSlot == 2 ? "BlueBrush" : shownSlot == 3 ? "AmberBrush" : "PurpBrush"];
            AudioBtn.Text          = Short(AudioManager.SlotLabel(cfg, nextSlot));
        }

        // HdrStatus/HdrBtn are pre-populated by ShowPopup() before the window is shown,
        // so do not reset them to "ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬ÂÃƒâ€šÃ‚Â ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â·ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â·ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â·" here ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â that would cause the exact flicker
        // we're trying to avoid. The async detection below will still update them if
        // the state has changed since the synchronous pre-check.
        if (!_brightnessCapturing)
            BrightnessLabel.Text = "...";

        _hdrCts?.Cancel();
        var cts = _hdrCts = new CancellationTokenSource();

        // Run HDR detection, brightness, and Auto HDR registry read in parallel
        var hdrTask     = Task.Run(() => HdrDetector.IsEnabled());
        var brtTask     = Task.Run(() => BrightnessService.Get());
        var autoHdrTask = Task.Run(() => AutoHdrService.GetState());
        bool hdrOn  = await hdrTask;
        int  brt    = await brtTask;
        var  autoHdr = await autoHdrTask;
        if (cts.IsCancellationRequested) return;
        if (_lastBrightnessCommand.HasValue &&
            DateTimeOffset.UtcNow - _lastBrightnessCommandUtc < TimeSpan.FromSeconds(8))
        {
            brt = _lastBrightnessCommand.Value;
        }

        RecalculateModeStatus(gopherOn, hdrOn, autoHdr, brt, cur, curDev.Name);

        HdrStatus.Text       = hdrOn ? "ON"  : "OFF";
        HdrStatus.Foreground = hdrOn ? (Brush)res["GoodBrush"] : (Brush)res["BadBrush"];
        HdrBtn.Text          = hdrOn ? "Turn Off" : "Turn On";

        // Software dim is an SDR-mode tool: when HDR turns on, the SDR Balance slider takes
        // over, so drop any active overlay and reset the reveal.
        _hdrOnLast = hdrOn;
        if (hdrOn)
        {
            if (DimOverlay.Level > 0) DimOverlay.SetLevel(0);
            _dimRevealed = false;
        }
        else
        {
            // HDR off: the Dim row shows whenever brightness is at 0, OR an overlay is
            // already active (e.g. set via the Stream Deck dim dial). Clearing on a
            // brightness *raise* is handled in HandleBrightnessCommitted — NOT here — so a
            // dial-set dim isn't wiped by a passive refresh.
            _dimRevealed = brt == 0;
        }

        // Suppress slider events for ALL layout/visibility/value changes below ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â
        // WPF can fire ValueChanged on Slider when Visibility goes CollapsedÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢Visible
        // during template application, which would call HdrSliderService.Set unexpectedly.
        _suppressSliders = true;

        var brtVis = (!hdrOn && cfg.BrightnessSliderEnabled) ? Visibility.Visible : Visibility.Collapsed;
        var sdrVis = (hdrOn  && cfg.SdrSliderEnabled)        ? Visibility.Visible : Visibility.Collapsed;
        BrightnessDimLabel.Visibility = brtVis;
        BrightnessLabel.Visibility    = brtVis;
        BrightnessSlider.Visibility   = brtVis;
        SdrDimLabel.Visibility        = sdrVis;
        SdrValueLabel.Visibility      = sdrVis;
        SdrSlider.Visibility          = sdrVis;

        // Dim row: only under the brightness slider (HDR off), and only once revealed by
        // the brightness-at-0 gesture or while an overlay is already active.
        bool dimShow = brtVis == Visibility.Visible && (DimOverlay.Level > 0 || _dimRevealed);
        var dimVis = dimShow ? Visibility.Visible : Visibility.Collapsed;
        DimDimLabel.Visibility   = dimVis;
        DimValueLabel.Visibility = dimVis;
        DimSlider.Visibility     = dimVis;
        DimSlider.Value          = DimOverlay.Level;
        DimValueLabel.Text       = $"{DimOverlay.Level}%";

        // Auto HDR row: only when HDR is on AND the user hasn't hidden it in settings.
        var autoHdrVis = (hdrOn && cfg.AutoHdrEnabled) ? Visibility.Visible : Visibility.Collapsed;
        AutoHdrLabel.Visibility     = autoHdrVis;
        AutoHdrStatus.Visibility    = autoHdrVis;
        AutoHdrBtnBorder.Visibility = autoHdrVis;

        // Card height matrix:
        // HDR off  + brt slider        ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ 100   HDR off  + no slider          ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ 70
        // HDR on   + sdr + auto HDR    ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ 140   HDR on   + no sdr + auto HDR  ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ 100
        // HDR on   + sdr + no auto HDR ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ 100   HDR on   + no sdr + no auto   ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ 70
        DisplayCard.Height = hdrOn
            ? (autoHdrVis == Visibility.Visible
                ? (sdrVis == Visibility.Visible ? 140 : 100)
                : (sdrVis == Visibility.Visible ? 100 : 70))
            : (brtVis == Visibility.Visible ? (dimShow ? 140 : 100) : 70);
        LayoutCards();
        RaiseAboveDim();

        if (_brightnessCapturing)
        {
            BrightnessSlider.IsEnabled = true;
        }
        else if (brt >= 0)
        {
            BrightnessSlider.Value     = brt;
            BrightnessLabel.Text       = $"{brt}%";
            BrightnessSlider.IsEnabled = true;
        }
        else
        {
            BrightnessLabel.Text       = "N/A";
            BrightnessSlider.IsEnabled = false;
        }
        SdrSlider.IsEnabled = HdrSliderService.IsSupported;
        SdrDimLabel.Text    = HdrSliderService.IsSupported ? "SDR Balance" : "SDR Balance (not supported)";

        // SDR slider uses saved app value ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â see comment near CommitSdr for why.
        if (sdrVis == Visibility.Visible)
        {
            double saved = cfg.SdrBrightness;
            SdrSlider.Value    = saved;
            SdrValueLabel.Text = $"{saved:F1}";
        }

        // Auto HDR row position and state (only runs when hdrOn ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â row is hidden otherwise).
        if (hdrOn)
        {
            // Reposition: below SDR slider when visible, directly below HDR row otherwise.
            // Slider bottom = Canvas.Top(73) + Height(22) = 95; 8px gap ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ ahY = 103.
            double ahY = sdrVis == Visibility.Visible ? 103 : 54;
            Canvas.SetTop(AutoHdrLabel,     ahY);
            Canvas.SetTop(AutoHdrStatus,    ahY + 16);
            Canvas.SetTop(AutoHdrBtnBorder, ahY - 2);

            switch (autoHdr)
            {
                case AutoHdrService.State.On:
                    AutoHdrStatus.Text       = "ON";
                    AutoHdrStatus.Foreground = (Brush)res["GoodBrush"];
                    AutoHdrBtn.Text          = "Turn Off";
                    AutoHdrBtnBorder.Cursor  = Cursors.Hand;
                    AutoHdrBtnBorder.Opacity = 1.0;
                    break;
                case AutoHdrService.State.Off:
                    AutoHdrStatus.Text       = "OFF";
                    AutoHdrStatus.Foreground = (Brush)res["BadBrush"];
                    AutoHdrBtn.Text          = "Turn On";
                    AutoHdrBtnBorder.Cursor  = Cursors.Hand;
                    AutoHdrBtnBorder.Opacity = 1.0;
                    break;
                default: // Unknown ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â registry key/field missing
                    AutoHdrStatus.Text       = "Unavailable";
                    AutoHdrStatus.Foreground = (Brush)res["DimBrush"];
                    AutoHdrBtn.Text          = "N/A";
                    AutoHdrBtnBorder.Cursor  = Cursors.Arrow;
                    AutoHdrBtnBorder.Opacity = 0.45;
                    break;
            }
        }

        _suppressSliders = false;

        UpdateCouchButton();
        UpdateMorningButton();
        WriteStatusJson(gopherOn, hdrOn, autoHdr, AudioStatus.Text, brt);
    }

    private void WriteStatusJson(bool gopherOn, bool hdrOn, AutoHdrService.State autoHdr, string audioLabel, int brightness)
    {
        try
        {
            Directory.CreateDirectory(AppPaths.Config);
            var cfg = AppSettings.Current;
            var curDev = AudioManager.GetCurrentDefault();
            // Which configured slot (1/2/3) is the live default, falling back to the card's
            // displayed label and finally to slot 1 (matching what the Audio card shows).
            int curSlot = AudioManager.CurrentSlot(cfg, curDev.Id, curDev.Name);
            if (curSlot == 0 && AudioManager.Normalize(audioLabel) == AudioManager.Normalize(cfg.Device2Label)) curSlot = 2;
            if (curSlot == 0 && !string.IsNullOrEmpty(cfg.Device3Id) &&
                AudioManager.Normalize(audioLabel) == AudioManager.Normalize(cfg.Device3Label)) curSlot = 3;
            if (curSlot == 0) curSlot = 1;

            var status = new
            {
                updatedUtc = DateTimeOffset.UtcNow,
                gopher = gopherOn,
                hdr = hdrOn,
                autoHdr = autoHdr == AutoHdrService.State.Unknown ? (bool?)null : autoHdr == AutoHdrService.State.On,
                couchMode = cfg.Couch.Active,
                morningMode = cfg.Morning.Active,
                audio = AudioManager.SlotLabel(cfg, curSlot),
                audioDeviceIndex = curSlot,
                device1 = cfg.Device1Label,
                device2 = cfg.Device2Label,
                device3 = cfg.Device3Label,
                displayBrightness = brightness >= 0 ? brightness : (int?)null,
                sdrBrightness = cfg.SdrBrightness,
                dim = DimOverlay.Level,
                prayerStatus = _latestPrayerStatus,
                prayerCountdown = _latestPrayerCountdown,
            };
            WriteStatusJsonAtomic(JsonSerializer.Serialize(status));
        }
        catch (Exception ex) { Logger.Log($"WriteStatusJson: {ex.Message}"); }
    }

    private void WritePrayerStatusJson()
    {
        try
        {
            Directory.CreateDirectory(AppPaths.Config);
            JsonObject status;
            if (File.Exists(AppPaths.StatusJson))
            {
                status = JsonNode.Parse(File.ReadAllText(AppPaths.StatusJson)) as JsonObject ?? new JsonObject();
            }
            else
            {
                status = new JsonObject();
            }

            status["updatedUtc"] = DateTimeOffset.UtcNow.ToString("O");
            status["prayerStatus"] = _latestPrayerStatus;
            status["prayerCountdown"] = _latestPrayerCountdown;
            WriteStatusJsonAtomic(status.ToJsonString());
        }
        catch (Exception ex) { Logger.Log($"WritePrayerStatusJson: {ex.Message}"); }
    }

    private void WriteSliderStatusJson(int? displayBrightness = null, double? sdrBrightness = null, int? dim = null)
    {
        try
        {
            Directory.CreateDirectory(AppPaths.Config);
            JsonObject status;
            if (File.Exists(AppPaths.StatusJson))
            {
                status = JsonNode.Parse(File.ReadAllText(AppPaths.StatusJson)) as JsonObject ?? new JsonObject();
            }
            else
            {
                status = new JsonObject();
            }

            status["updatedUtc"] = DateTimeOffset.UtcNow.ToString("O");
            if (displayBrightness.HasValue) status["displayBrightness"] = displayBrightness.Value;
            if (sdrBrightness.HasValue) status["sdrBrightness"] = sdrBrightness.Value;
            if (dim.HasValue) status["dim"] = dim.Value;
            WriteStatusJsonAtomic(status.ToJsonString());
        }
        catch (Exception ex) { Logger.Log($"WriteSliderStatusJson: {ex.Message}"); }
    }

    // ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ Scenes (Couch / Morning) ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬
    private static void WriteStatusJsonAtomic(string json)
    {
        Directory.CreateDirectory(AppPaths.Config);
        string tempPath = Path.Combine(AppPaths.Config, $"status.{Guid.NewGuid():N}.tmp");
        File.WriteAllText(tempPath, json);
        File.Move(tempPath, AppPaths.StatusJson, true);
    }

    // Couch and Morning are two "scenes": press once to drive the display/audio/gopher
    // to a set of targets (snapshotting the current state first), press again to restore
    // that snapshot. Both run through the same ApplyScene* engine so the SDR-only
    // brightness ordering lives in one place; they differ only in their SceneSpec targets.

    // Desired targets for a scene. ManageX = "this scene controls X"; the *On flag is the
    // target value when managed.
    private sealed class SceneSpec
    {
        public string Name = "Scene";
        public bool SaveState;
        public bool ManageGopher;  public bool GopherOn;
        public bool ManageHdr;     public bool HdrOn;
        public bool ManageAutoHdr; public bool AutoHdrOn;
        public bool ManageBrightness; public int BrightnessTarget;
        public bool ManageAudio;   public string AudioId = ""; public string AudioLabel = "";
    }

    private static SceneSpec BuildCouchSpec(CouchModeConfig c) => new()
    {
        Name = "Couch", SaveState = c.SaveStateBeforeApply,
        ManageGopher = c.ToggleGopher, GopherOn = true,    // Couch: Gopher ON
        ManageHdr    = c.ToggleHdr,    HdrOn    = false,   // Couch: HDR OFF
        ManageAutoHdr = false,
        ManageBrightness = c.SetBrightness, BrightnessTarget = c.TargetBrightness,
        ManageAudio  = c.SwitchAudio,  AudioId  = c.TargetAudioId, AudioLabel = c.TargetAudioLabel,
    };

    private static SceneSpec BuildMorningSpec(MorningModeConfig m) => new()
    {
        Name = "Morning", SaveState = m.SaveStateBeforeApply,
        ManageGopher = m.ManageGopher, GopherOn = false,   // Morning: Gopher OFF
        ManageHdr    = m.ManageHdr,    HdrOn    = true,    // Morning: HDR ON
        ManageAutoHdr = m.ManageAutoHdr, AutoHdrOn = true, // Morning: Auto HDR ON
        ManageBrightness = false,                          // Morning leaves brightness alone
        ManageAudio  = m.SwitchAudio,  AudioId  = m.TargetAudioId, AudioLabel = m.TargetAudioLabel,
    };

    private static void RecalculateModeStatus(
        bool gopherOn,
        bool hdrOn,
        AutoHdrService.State autoHdr,
        int brightness,
        string currentAudioId,
        string currentAudioName)
    {
        var cfg = AppSettings.Current;
        bool changed = false;

        if (cfg.Couch.Active &&
            !SceneMatches(BuildCouchSpec(cfg.Couch), gopherOn, hdrOn, autoHdr, brightness, currentAudioId, currentAudioName))
        {
            Logger.Log("Couch Mode: real state no longer matches preset; marking OFF and clearing restore snapshot");
            cfg.Couch.Active = false;
            cfg.Couch.Saved = null;
            changed = true;
        }

        if (cfg.Morning.Active &&
            !SceneMatches(BuildMorningSpec(cfg.Morning), gopherOn, hdrOn, autoHdr, brightness, currentAudioId, currentAudioName))
        {
            Logger.Log("Morning Mode: real state no longer matches preset; marking OFF and clearing restore snapshot");
            cfg.Morning.Active = false;
            cfg.Morning.Saved = null;
            changed = true;
        }

        if (changed)
        {
            cfg.Save();
            AppSettings.Invalidate();
        }
    }

    private async Task RecalculateModeStatusFromRealState()
    {
        var curDev = AudioManager.GetCurrentDefault();
        var hdrTask = Task.Run(() => HdrDetector.IsEnabled());
        var brtTask = Task.Run(() => BrightnessService.Get());
        var autoHdrTask = Task.Run(() => AutoHdrService.GetState());

        RecalculateModeStatus(
            GopherManager.IsRunning,
            await hdrTask,
            await autoHdrTask,
            await brtTask,
            curDev.Id,
            curDev.Name);
    }

    private static bool SceneMatches(
        SceneSpec spec,
        bool gopherOn,
        bool hdrOn,
        AutoHdrService.State autoHdr,
        int brightness,
        string currentAudioId,
        string currentAudioName)
    {
        if (spec.ManageGopher && gopherOn != spec.GopherOn) return false;
        if (spec.ManageHdr && hdrOn != spec.HdrOn) return false;

        if (spec.ManageAutoHdr)
        {
            if (autoHdr == AutoHdrService.State.Unknown) return false;
            if ((autoHdr == AutoHdrService.State.On) != spec.AutoHdrOn) return false;
        }

        if (spec.ManageBrightness)
        {
            if (brightness < 0) return false;
            if (Math.Abs(brightness - spec.BrightnessTarget) > 2) return false;
        }

        if (spec.ManageAudio && (!string.IsNullOrEmpty(spec.AudioId) || !string.IsNullOrEmpty(spec.AudioLabel)) &&
            !AudioTargetMatches(currentAudioId, currentAudioName, spec.AudioId, spec.AudioLabel))
            return false;

        return true;
    }

    private static bool AudioTargetMatches(string currentAudioId, string currentAudioName, string targetAudioId, string targetLabel)
    {
        if (string.IsNullOrEmpty(targetAudioId) && string.IsNullOrEmpty(targetLabel)) return true;
        if (!string.IsNullOrEmpty(targetAudioId) && currentAudioId == targetAudioId) return true;

        // Resolve the target's name from the live device list by ID; if the saved ID is
        // stale (no longer a live endpoint) fall back to the saved label, so a switch that
        // succeeded by name still counts as a match.
        var devices = AudioManager.GetRenderDevices();
        var target = devices.FirstOrDefault(d => d.Id == targetAudioId);
        string targetName = !string.IsNullOrEmpty(target.Name) ? target.Name : targetLabel;

        return !string.IsNullOrEmpty(targetName) &&
               !string.IsNullOrEmpty(currentAudioName) &&
               AudioManager.Normalize(currentAudioName) == AudioManager.Normalize(targetName);
    }

    private void UpdateCouchButton()   => UpdateSceneStatus(CouchModeBtn,   CouchModeStatus,
        AppSettings.Current.Couch.Active,   AppSettings.Current.Couch.Configured,   "Couch Mode");
    private void UpdateMorningButton() => UpdateSceneStatus(MorningModeBtn, MorningModeStatus,
        AppSettings.Current.Morning.Active, AppSettings.Current.Morning.Configured, "Morning Mode");

    private static void UpdateSceneStatus(Border btn, TextBlock status, bool active, bool configured, string name)
    {
        var res = Application.Current.Resources;

        // Not set up yet: dim the pill, show a "Setup" hint, and explain via tooltip.
        // The toggle handlers refuse to run until the mode is configured in Settings.
        if (!configured)
        {
            status.Text       = "Setup";
            status.Foreground = (Brush)res["DimBrush"];
            btn.Opacity       = 0.55;
            btn.ToolTip       = $"Set up {name} in Settings first.";
            return;
        }

        btn.Opacity       = 1.0;
        btn.ToolTip       = null;
        status.Text       = active ? "ON" : "OFF";
        status.Foreground = active ? (Brush)res["GoodBrush"] : (Brush)res["BadBrush"];
    }

    private async void OnCouchModeClick(object sender, MouseButtonEventArgs e)
    {
        if (_editMode) { e.Handled = true; return; }
        e.Handled = true;
        await RunCouchToggle();
        Activate();
    }

    private async void OnMorningModeClick(object sender, MouseButtonEventArgs e)
    {
        if (_editMode) { e.Handled = true; return; }
        e.Handled = true;
        await RunMorningToggle();
        Activate();
    }

    // Toggles Couch Mode on/off. Safe to call from the tray/CLI even while the popup
    // is hidden (only touches window-owned UI elements, never Activates/Shows).
    public async Task RunCouchToggle()
    {
        if (!AppSettings.Current.Couch.Configured)  // not set up yet — leave the pill in its "Setup" state
        {
            Logger.Log("Couch Mode toggle ignored: not configured in Settings");
            UpdateCouchButton();
            return;
        }
        if (_sceneInProgress) return;              // ignore re-entrancy / overlap with Morning
        _sceneInProgress  = true;
        _actionInProgress = true;                  // keep popup open during the toggle
        CouchModeStatus.Text = "...";
        try
        {
            await RecalculateModeStatusFromRealState();
            var couch = AppSettings.Current.Couch;

            if (!couch.Active)
            {
                // Scenes are mutually exclusive: restore Morning to baseline first, so its
                // status reads OFF and any state it changed (e.g. HDR) is undone before
                // Couch snapshots and applies its own targets.
                await DeactivateMorning();
                couch.Saved  = await ApplySceneOn(BuildCouchSpec(couch));
                couch.Active = true;
            }
            else
            {
                await ApplySceneOff(BuildCouchSpec(couch), couch.Saved);
                couch.Active = false; couch.Saved = null;
            }

            AppSettings.Current.Save();
            AppSettings.Invalidate();
            if (IsVisible) RefreshState();          // reflect HDR/brightness/audio changes
        }
        catch (Exception ex) { Logger.Log($"CouchToggle: {ex.Message}"); }
        finally
        {
            _sceneInProgress  = false;
            _actionInProgress = false;
            UpdateCouchButton();
            UpdateMorningButton();
        }
    }

    // Toggles Morning Mode on/off. Mirror of RunCouchToggle.
    public async Task RunMorningToggle()
    {
        if (!AppSettings.Current.Morning.Configured)  // not set up yet — leave the pill in its "Setup" state
        {
            Logger.Log("Morning Mode toggle ignored: not configured in Settings");
            UpdateMorningButton();
            return;
        }
        if (_sceneInProgress) return;
        _sceneInProgress  = true;
        _actionInProgress = true;
        MorningModeStatus.Text = "...";
        try
        {
            await RecalculateModeStatusFromRealState();
            var morning = AppSettings.Current.Morning;

            if (!morning.Active)
            {
                await DeactivateCouch();            // mutual exclusivity (see RunCouchToggle)
                morning.Saved  = await ApplySceneOn(BuildMorningSpec(morning));
                morning.Active = true;
            }
            else
            {
                await ApplySceneOff(BuildMorningSpec(morning), morning.Saved);
                morning.Active = false; morning.Saved = null;
            }

            AppSettings.Current.Save();
            AppSettings.Invalidate();
            if (IsVisible) RefreshState();
        }
        catch (Exception ex) { Logger.Log($"MorningToggle: {ex.Message}"); }
        finally
        {
            _sceneInProgress  = false;
            _actionInProgress = false;
            UpdateCouchButton();
            UpdateMorningButton();
        }
    }

    // Restores a scene to its saved baseline if active, without persisting/refreshing
    // (the caller does that). Used to enforce one-scene-at-a-time: turning one scene on
    // first turns the other off so its button shows the real OFF status.
    private async Task DeactivateCouch()
    {
        var c = AppSettings.Current.Couch;
        if (!c.Active) return;
        await ApplySceneOff(BuildCouchSpec(c), c.Saved);
        c.Active = false; c.Saved = null;
    }

    private async Task DeactivateMorning()
    {
        var m = AppSettings.Current.Morning;
        if (!m.Active) return;
        await ApplySceneOff(BuildMorningSpec(m), m.Saved);
        m.Active = false; m.Saved = null;
    }

    // Applies a scene's targets, returning the snapshot to restore later (null if the
    // scene doesn't save state).
    private async Task<SceneSnapshot?> ApplySceneOn(SceneSpec spec)
    {
        Logger.Log($"{spec.Name} Mode: turning ON");

        SceneSnapshot? snap = null;
        if (spec.SaveState)
        {
            snap = new SceneSnapshot
            {
                GopherWasRunning = GopherManager.IsRunning,
                HdrWasOn         = await Task.Run(() => HdrDetector.IsEnabled()),
                AutoHdrWasOn     = await Task.Run(() => AutoHdrService.GetState()) == AutoHdrService.State.On,
                PrevBrightness   = await Task.Run(() => BrightnessService.Get()),
                PrevAudioId      = AudioManager.GetCurrentDefaultId(),
            };
            Logger.Log($"{spec.Name} Mode: saved state gopher={snap.GopherWasRunning} hdr={snap.HdrWasOn} " +
                       $"autohdr={snap.AutoHdrWasOn} brt={snap.PrevBrightness} audio={snap.PrevAudioId}");
        }

        if (spec.ManageGopher)
            GopherManager.EnsureRunning(spec.GopherOn);

        await DriveHdrAndBrightness(spec.ManageHdr, spec.HdrOn, spec.ManageBrightness, spec.BrightnessTarget, spec.Name);

        if (spec.ManageAutoHdr)
            await SetAutoHdrState(spec.AutoHdrOn, spec.Name);

        if (spec.ManageAudio && (!string.IsNullOrEmpty(spec.AudioId) || !string.IsNullOrEmpty(spec.AudioLabel)))
            await Task.Run(() => AudioManager.TrySetDefaultByIdOrName(spec.AudioId, spec.AudioLabel));

        return snap;
    }

    // Restores the snapshot taken when the scene was turned on.
    private async Task ApplySceneOff(SceneSpec spec, SceneSnapshot? s)
    {
        Logger.Log($"{spec.Name} Mode: turning OFF (restoring)");
        if (s is null) { Logger.Log($"{spec.Name} Mode: no saved state ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â nothing to restore"); return; }

        if (spec.ManageGopher)
            GopherManager.EnsureRunning(s.GopherWasRunning);

        await DriveHdrAndBrightness(spec.ManageHdr, s.HdrWasOn, spec.ManageBrightness, s.PrevBrightness, $"{spec.Name} restore");

        if (spec.ManageAutoHdr)
            await SetAutoHdrState(s.AutoHdrWasOn, spec.Name);

        if (spec.ManageAudio && !string.IsNullOrEmpty(s.PrevAudioId))
            await Task.Run(() => AudioManager.TrySetDefault(s.PrevAudioId));
    }

    // Drives HDR to a target and (optionally) brightness to a target, ordering the two so
    // the brightness write always lands while the panel is in SDR. DDC/CI brightness only
    // takes effect in SDR on this hardware: under HDR the high-level SetMonitorBrightness
    // fails (err 0xC0262582) and the VCP fallback reports success but the panel ignores it.
    // So: turning HDR OFF ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ flip HDR first, then write brightness; turning HDR ON ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ write
    // brightness first (still SDR), then flip HDR. (HDR-on Get still reads correctly, only
    // Set is affected, so the snapshot itself is reliable.)
    private async Task DriveHdrAndBrightness(bool manageHdr, bool hdrTarget, bool manageBrt, int brtTarget, string ctx)
    {
        if (manageBrt && brtTarget < 0) manageBrt = false;   // unknown brightness ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ skip

        if (manageHdr && hdrTarget)
        {
            if (manageBrt) await SetBrightnessLogged(brtTarget, ctx);
            await SetHdrState(true);
        }
        else if (manageHdr && !hdrTarget)
        {
            await SetHdrState(false);
            if (manageBrt) await SetBrightnessLogged(brtTarget, ctx);
        }
        else if (manageBrt)
        {
            await SetBrightnessLogged(brtTarget, ctx);   // HDR not managed ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â write in current mode
        }
    }

    private static async Task SetBrightnessLogged(int percent, string ctx)
    {
        await Task.Run(() => BrightnessService.Set(percent));
    }

    // Drives Auto HDR to a target state (only if it differs). No-op when the registry
    // value is missing/unreadable (State.Unknown).
    private static async Task SetAutoHdrState(bool desired, string ctx)
    {
        var st = await Task.Run(() => AutoHdrService.GetState());
        if (st == AutoHdrService.State.Unknown) return;
        if ((st == AutoHdrService.State.On) == desired) return;

        await Task.Run(() => AutoHdrService.Toggle(st));
    }

    // Drives HDR to a specific state via Win+Alt+B, but only if it isn't already there
    // (avoids needless toggles). When turning HDR back ON, re-applies the saved SDR
    // brightness ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â Windows resets the DWM SDR boost on every HDR session start
    // (same fix as OnHdrClick).
    private async Task SetHdrState(bool desired)
    {
        bool on = await Task.Run(() => HdrDetector.IsEnabled());
        if (on == desired) return;

        SendHdrKeys();
        await Task.Delay(700);

        if (desired && HdrSliderService.IsSupported)
        {
            double saved = ClampSdr(AppSettings.Current.SdrBrightness);
            await Task.Run(() => HdrSliderService.Set(saved));
        }
    }

    private void ToggleCouch(string which)
    {
        var c = AppSettings.Current.Couch;
        switch (which)
        {
            case "Gopher":     c.ToggleGopher         = !c.ToggleGopher;         break;
            case "Hdr":        c.ToggleHdr            = !c.ToggleHdr;            break;
            case "Brightness": c.SetBrightness        = !c.SetBrightness;        break;
            case "Audio":      c.SwitchAudio          = !c.SwitchAudio;          break;
            case "SaveState":  c.SaveStateBeforeApply = !c.SaveStateBeforeApply; break;
        }
        c.Configured = true;
        AppSettings.Current.Save();
        AppSettings.Invalidate();
        RefreshSettingsPanel();
    }

    private void ShowCouchAudioDropdown(Border anchor)
    {
        var devices = AudioManager.GetRenderDevices();
        if (devices.Count == 0) return;

        // Index 0 = "Select" (none); real devices follow at +1, so a target can be reset.
        var names  = new List<string> { "Select" };
        names.AddRange(devices.Select(d => d.Name));
        int found  = devices.FindIndex(d => d.Id == AppSettings.Current.Couch.TargetAudioId);
        int selIdx = found < 0 ? 0 : found + 1;

        var screenPt = anchor.PointToScreen(new Point(0, anchor.ActualHeight + 2));
        var drop = new DropdownWindow(names, selIdx, screenPt, (int)anchor.ActualWidth) { Owner = this };

        _actionInProgress = true;
        drop.Selected += idx =>
        {
            if (idx <= 0) OnCouchAudioClear();
            else          OnCouchAudioSelect(devices[idx - 1]);
        };
        drop.Closed   += (_, _) => _actionInProgress = false;
        drop.Show();
    }

    private void OnCouchAudioSelect((string Id, string Name) dev)
    {
        var cfg = AppSettings.Current;
        cfg.Couch.TargetAudioId    = dev.Id;
        cfg.Couch.TargetAudioLabel = dev.Name;
        cfg.Couch.Configured       = true;
        cfg.Save();
        AppSettings.Invalidate();
        if (_couchAudioText is not null) _couchAudioText.Text = dev.Name;
    }

    private void OnCouchAudioClear()
    {
        var cfg = AppSettings.Current;
        cfg.Couch.TargetAudioId    = "";
        cfg.Couch.TargetAudioLabel = "";
        cfg.Save();
        AppSettings.Invalidate();
        if (_couchAudioText is not null) _couchAudioText.Text = "Select...";
    }

    private void ToggleMorning(string which)
    {
        var m = AppSettings.Current.Morning;
        switch (which)
        {
            case "Gopher":    m.ManageGopher         = !m.ManageGopher;         break;
            case "Hdr":       m.ManageHdr            = !m.ManageHdr;            break;
            case "AutoHdr":   m.ManageAutoHdr        = !m.ManageAutoHdr;        break;
            case "Audio":     m.SwitchAudio          = !m.SwitchAudio;          break;
            case "SaveState": m.SaveStateBeforeApply = !m.SaveStateBeforeApply; break;
        }
        m.Configured = true;
        AppSettings.Current.Save();
        AppSettings.Invalidate();
        RefreshSettingsPanel();
    }

