ƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬

    // Converts a mouse position on a Slider to its value, accounting for the
    // 14px thumb (7px half-width) so clicking the track edges maps to Min/Max.
    private static double SliderValueFromMouse(Slider slider, System.Windows.Input.MouseEventArgs e)
    {
        const double thumbHalf = 9.0; // half of 18px thumb (ThinSlider)
        double trackW = slider.ActualWidth - thumbHalf * 2;
        if (trackW <= 0) return slider.Value;
        double ratio = Math.Clamp((e.GetPosition(slider).X - thumbHalf) / trackW, 0.0, 1.0);
        return slider.Minimum + ratio * (slider.Maximum - slider.Minimum);
    }

    // ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ Brightness slider ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬

    // ValueChanged: label only ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â system write happens once on mouse release.
    private void OnBrightnessChanged(object sender, RoutedPropertyChangedEventArgs<double> e)
    {
        if (_suppressSliders) return;
        int pct = (int)Math.Round(e.NewValue);
        _lastBrightnessCommand = pct;
        _lastBrightnessCommandUtc = DateTimeOffset.UtcNow;
        BrightnessLabel.Text = $"{pct}%";
        WriteSliderStatusJson(displayBrightness: pct);
    }

    private void OnBrightnessSliderDown(object sender, MouseButtonEventArgs e)
    {
        if (_suppressSliders) return;
        _brightnessCapturing = true;
        BrightnessSlider.CaptureMouse();
        BrightnessSlider.Value = SliderValueFromMouse(BrightnessSlider, e);
        e.Handled = true;
    }

    private void OnBrightnessSliderMove(object sender, System.Windows.Input.MouseEventArgs e)
    {
        if (!_brightnessCapturing || e.LeftButton != MouseButtonState.Pressed) return;
        BrightnessSlider.Value = SliderValueFromMouse(BrightnessSlider, e);
    }

    private void OnBrightnessSliderUp(object sender, MouseButtonEventArgs e)
    {
        if (!_brightnessCapturing) return;
        _brightnessCapturing = false;
        BrightnessSlider.ReleaseMouseCapture();
        int pct = Math.Clamp((int)Math.Round(BrightnessSlider.Value), 0, 100);
        _lastBrightnessCommand = pct;
        _lastBrightnessCommandUtc = DateTimeOffset.UtcNow;
        WriteSliderStatusJson(displayBrightness: pct);
        QueueBrightnessSet(pct);
        HandleBrightnessCommitted(pct);
        e.Handled = true;
    }

    private async Task ApplyBrightnessDelta(double delta)
    {
        int current = BrightnessSlider.Visibility == Visibility.Visible && BrightnessSlider.IsEnabled
            ? (int)Math.Round(BrightnessSlider.Value)
            : await Task.Run(() => BrightnessService.Get());
        if (current < 0) current = 50;

        await ApplyBrightnessValue(current + delta);
    }

    private Task ApplyBrightnessValue(double value)
    {
        int pct = Math.Clamp((int)Math.Round(value), 0, 100);
        _lastBrightnessCommand = pct;
        _lastBrightnessCommandUtc = DateTimeOffset.UtcNow;
        WriteSliderStatusJson(displayBrightness: pct);

        _suppressSliders = true;
        BrightnessSlider.Value = pct;
        BrightnessLabel.Text = $"{pct}%";
        _suppressSliders = false;

        QueueBrightnessSet(pct);
        HandleBrightnessCommitted(pct);
        return Task.CompletedTask;
    }

    // ── Software dim (overlay below the hardware brightness floor) ─────────────

    // Called whenever hardware brightness is committed. At 0 the Dim slider reveals
    // immediately; above 0 any active dim is cleared (brightness is the master).
    private void HandleBrightnessCommitted(int pct)
    {
        if (_hdrOnLast) return;   // dim is HDR-off only

        if (pct <= 0)
        {
            if (!_dimRevealed) { _dimRevealed = true; UpdateDimRow(); }
            return;
        }

        if (_dimRevealed || DimOverlay.Level > 0)
        {
            DimOverlay.SetLevel(0);
            _dimRevealed = false;
            UpdateDimRow();
            WriteSliderStatusJson(dim: 0);
        }
    }

    // Reflows just the Dim row + Display card height between full RefreshState passes.
    private void UpdateDimRow()
    {
        var cfg = AppSettings.Current;
        bool dimShow = !_hdrOnLast && cfg.BrightnessSliderEnabled
                       && (DimOverlay.Level > 0 || _dimRevealed);
        var vis = dimShow ? Visibility.Visible : Visibility.Collapsed;

        _suppressSliders = true;
        DimDimLabel.Visibility   = vis;
        DimValueLabel.Visibility = vis;
        DimSlider.Visibility     = vis;
        DimSlider.Value          = DimOverlay.Level;
        DimValueLabel.Text       = $"{DimOverlay.Level}%";
        _suppressSliders = false;

        if (!_hdrOnLast)
            DisplayCard.Height = cfg.BrightnessSliderEnabled ? (dimShow ? 140 : 100) : 70;
        LayoutCards();
        RaiseAboveDim();
    }

    [DllImport("user32.dll", SetLastError = true)]
    private static extern bool SetWindowPos(IntPtr hWnd, IntPtr hWndInsertAfter,
        int X, int Y, int cx, int cy, uint uFlags);
    private static readonly IntPtr HWND_TOPMOST = new(-1);
    private const uint SWP_NOMOVE     = 0x0002;
    private const uint SWP_NOSIZE     = 0x0001;
    private const uint SWP_NOACTIVATE = 0x0010;

    // ── Global click-away hook (WH_MOUSE_LL) ───────────────────────────────────────────
    // Closes the popup on a click outside it even when the window was never activated
    // (Stream Deck / CLI shows over a fullscreen app). Listens only — never swallows the
    // click — so the underlying app still receives it.
    private delegate IntPtr LowLevelMouseProc(int nCode, IntPtr wParam, IntPtr lParam);

    [DllImport("user32.dll", SetLastError = true)]
    private static extern IntPtr SetWindowsHookEx(int idHook, LowLevelMouseProc lpfn, IntPtr hMod, uint dwThreadId);
    [DllImport("user32.dll", SetLastError = true)]
    private static extern bool UnhookWindowsHookEx(IntPtr hhk);
    [DllImport("user32.dll")]
    private static extern IntPtr CallNextHookEx(IntPtr hhk, int nCode, IntPtr wParam, IntPtr lParam);
    [DllImport("kernel32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    private static extern IntPtr GetModuleHandle(string? lpModuleName);

    private const int WH_MOUSE_LL    = 14;
    private const int WM_LBUTTONDOWN = 0x0201;
    private const int WM_RBUTTONDOWN = 0x0204;
    private const int WM_MBUTTONDOWN = 0x0207;

    [StructLayout(LayoutKind.Sequential)]
    private struct MSLLHOOKSTRUCT { public int x; public int y; public uint mouseData; public uint flags; public uint time; public IntPtr dwExtraInfo; }

    private void InstallMouseHook()
    {
        if (_mouseHook != IntPtr.Zero) return; // already hooked
        _mouseHookProc = MouseHookCallback;    // hold a ref so the GC can't collect it mid-callback
        // A WH_MOUSE_LL hook needs a valid module handle; the current process module works.
        using var proc = System.Diagnostics.Process.GetCurrentProcess();
        using var mod  = proc.MainModule;
        IntPtr hMod = mod is null ? IntPtr.Zero : GetModuleHandle(mod.ModuleName);
        _mouseHook = SetWindowsHookEx(WH_MOUSE_LL, _mouseHookProc, hMod, 0);
        if (_mouseHook == IntPtr.Zero) Logger.Log("InstallMouseHook: SetWindowsHookEx failed");
    }

    private void RemoveMouseHook()
    {
        if (_mouseHook == IntPtr.Zero) return;
        UnhookWindowsHookEx(_mouseHook);
        _mouseHook     = IntPtr.Zero;
        _mouseHookProc = null;
    }

    private IntPtr MouseHookCallback(int nCode, IntPtr wParam, IntPtr lParam)
    {
        if (nCode >= 0)
        {
            int msg = (int)wParam;
            if (msg == WM_LBUTTONDOWN || msg == WM_RBUTTONDOWN || msg == WM_MBUTTONDOWN)
            {
                var hs = Marshal.PtrToStructure<MSLLHOOKSTRUCT>(lParam);
                // Runs on the UI thread (LL hooks dispatch on the installing thread's message
                // loop), but defer the actual hide so we don't tear down the window mid-callback.
                Dispatcher.BeginInvoke(new Action(() => DismissIfOutside(hs.x, hs.y)));
            }
        }
        return CallNextHookEx(_mouseHook, nCode, wParam, lParam);
    }

    // Closes the popup if the click point (physical screen px) is outside the visible popup.
    // Mirrors the OnDeactivated guards so an outside click can't blow away an open settings
    // panel, edit mode, help bubble, or an in-flight action (incl. an open dropdown).
    private void DismissIfOutside(int xPx, int yPx)
    {
        if (!IsVisible) return;
        if (_actionInProgress || _settingsExpanded || _editMode || HelpPopup.IsOpen || UpdateNotesPopup.IsOpen) return;
        try
        {
            Point tl = PopupBorder.PointToScreen(new Point(0, 0));
            Point br = PopupBorder.PointToScreen(new Point(PopupBorder.ActualWidth, PopupBorder.ActualHeight));
            bool inside = xPx >= tl.X && xPx <= br.X && yPx >= tl.Y && yPx <= br.Y;
            if (!inside) HidePopupFromUser();
        }
        catch { /* layout not ready — leave the popup open */ }
    }

    // The overlay and the popup are both top-most; re-assert the popup to the top of the
    // top-most band so the control you're using never gets dimmed by its own overlay.
    // SetWindowPos reorders in place (unlike toggling Topmost, which briefly drops the
    // window out of the band and makes it flicker as the overlay covers it for a frame).
    private void RaiseAboveDim()
    {
        if (DimOverlay.Level <= 0 || !IsVisible) return;
        var hwnd = new System.Windows.Interop.WindowInteropHelper(this).Handle;
        if (hwnd != IntPtr.Zero)
            SetWindowPos(hwnd, HWND_TOPMOST, 0, 0, 0, 0,
                SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE);
    }

    private void OnDimChanged(object sender, RoutedPropertyChangedEventArgs<double> e)
    {
        if (_suppressSliders) return;
        int pct = (int)Math.Round(e.NewValue);
        DimValueLabel.Text = $"{pct}%";
        DimOverlay.SetLevel(pct);
        RaiseAboveDim();
        WriteSliderStatusJson(dim: pct);
    }

    private void OnDimSliderDown(object sender, MouseButtonEventArgs e)
    {
        if (_suppressSliders) return;
        _dimCapturing = true;
        DimSlider.CaptureMouse();
        DimSlider.Value = SliderValueFromMouse(DimSlider, e);
        e.Handled = true;
    }

    private void OnDimSliderMove(object sender, System.Windows.Input.MouseEventArgs e)
    {
        if (!_dimCapturing || e.LeftButton != MouseButtonState.Pressed) return;
        DimSlider.Value = SliderValueFromMouse(DimSlider, e);
    }

    private void OnDimSliderUp(object sender, MouseButtonEventArgs e)
    {
        if (!_dimCapturing) return;
        _dimCapturing = false;
        DimSlider.ReleaseMouseCapture();
        e.Handled = true;
    }

    // Stream Deck Dim dial entry point: set the software dim overlay directly, 0–100.
    private Task ApplyDimValue(double value)
    {
        int pct = Math.Clamp((int)Math.Round(value), 0, 100);
        DimOverlay.SetLevel(pct);
        UpdateDimRow();
        WriteSliderStatusJson(dim: pct);
        return Task.CompletedTask;
    }

    private void QueueBrightnessSet(int pct)
    {
        _pendingBrightnessSet = pct;
        if (_brightnessSetInProgress) return;
        _ = RunBrightnessSetQueueAsync();
    }

    private async Task RunBrightnessSetQueueAsync()
    {
        _brightnessSetInProgress = true;
        try
        {
            while (_pendingBrightnessSet.HasValue)
            {
                int pct = _pendingBrightnessSet.Value;
                _pendingBrightnessSet = null;
                await Task.Run(() => BrightnessService.Set(pct));
            }
        }
        finally
        {
            _brightnessSetInProgress = false;
        }

        if (_pendingBrightnessSet.HasValue)
        {
            _ = RunBrightnessSetQueueAsync();
            return;
        }

        RefreshState();
    }

    // ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ SDR Balance slider ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬
    // ValueChanged: label only ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â HdrSliderService.Set called once on release.

    private void OnSdrChanged(object sender, RoutedPropertyChangedEventArgs<double> e)
    {
        if (_suppressSliders) return;
        double val = ClampSdr(Math.Round(e.NewValue, 1));
        SdrValueLabel.Text = $"{val:F1}";
        WriteSliderStatusJson(sdrBrightness: val);
    }

    private void OnSdrSliderDown(object sender, MouseButtonEventArgs e)
    {
        if (_suppressSliders) return;
        _sdrCapturing = true;
        SdrSlider.CaptureMouse();
        SdrSlider.Value = SliderValueFromMouse(SdrSlider, e);
        e.Handled = true;
    }

    private void OnSdrSliderMove(object sender, System.Windows.Input.MouseEventArgs e)
    {
        if (!_sdrCapturing || e.LeftButton != MouseButtonState.Pressed) return;
        SdrSlider.Value = SliderValueFromMouse(SdrSlider, e);
    }

    private void OnSdrSliderUp(object sender, MouseButtonEventArgs e)
    {
        if (!_sdrCapturing) return;
        _sdrCapturing = false;
        SdrSlider.ReleaseMouseCapture();
        CommitSdr();
        e.Handled = true;
    }

    private void CommitSdr()
    {
        double val = ClampSdr(Math.Round(SdrSlider.Value, 1));
        Logger.Log($"CommitSdr: user-initiated, applying {val:F1}");
        var cfg = AppSettings.Current;
        cfg.SdrBrightness = val;
        cfg.Save();
        AppSettings.Invalidate();
        _ = Task.Run(() => HdrSliderService.Set(val))
            .ContinueWith(_ => Dispatcher.BeginInvoke(new Action(RefreshState)));
    }

    private async Task ApplySdrDelta(double delta)
    {
        var cfg = AppSettings.Current;
        await ApplySdrValue(cfg.SdrBrightness + delta);
    }

    private Task ApplySdrValue(double value)
    {
        var cfg = AppSettings.Current;
        double val = ClampSdr(Math.Round(value, 1));
        Logger.Log($"StreamDeck SDR dial: applying {val:F1}");
        cfg.SdrBrightness = val;
        cfg.Save();
        AppSettings.Invalidate();
        WriteSliderStatusJson(sdrBrightness: val);

        _suppressSliders = true;
        SdrSlider.Value = val;
        SdrValueLabel.Text = $"{val:F1}";
        _suppressSliders = false;

        QueueSdrSet(val);
        return Task.CompletedTask;
    }

    private void QueueSdrSet(double val)
    {
        _pendingSdrSet = val;
        if (_sdrSetInProgress) return;
        _ = RunSdrSetQueueAsync();
    }

    private async Task RunSdrSetQueueAsync()
    {
        _sdrSetInProgress = true;
        try
        {
            while (_pendingSdrSet.HasValue)
            {
                double val = _pendingSdrSet.Value;
                _pendingSdrSet = null;
                if (HdrSliderService.IsSupported)
                    await Task.Run(() => HdrSliderService.Set(val));
            }
        }
        finally
        {
            _sdrSetInProgress = false;
        }

        if (_pendingSdrSet.HasValue)
        {
            _ = RunSdrSetQueueAsync();
            return;
        }

        RefreshState();
    }

    // ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ Settings toggle ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â animates MaxHeight only, window never resizes ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬

    private void OnSettingsToggle(object sender, MouseButtonEventArgs e)
    {
        e.Handled = true;
        CollapseOrExpandSettings();
    }

    private void CollapseOrExpandSettings()
    {
        HideHelp();
        // When collapsing, save first ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â stay open if validation fails
        if (_settingsExpanded && !TrySaveSettings()) return;

        _settingsExpanded = !_settingsExpanded;
        SettingsToggleBtn.Text = _settingsExpanded ? "Close" : "Settings";

        // Collapsing Settings also collapses every accordion section, so it reopens fresh.
        if (!_settingsExpanded)
            foreach (var key in _sectionExpanded.Keys.ToList())
                _sectionExpanded[key] = false;

        if (_settingsExpanded)
        {
            BuildSettingsPanel(); // always rebuild ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â reflects current card order/visibility
            PopulateDropButtons();
            UpdatePrayerBtnStates();
        }

        double target = _settingsExpanded ? _settingsContentH : 0;
        var anim = new DoubleAnimation
        {
            To             = target,
            Duration       = TimeSpan.FromMilliseconds(220),
            EasingFunction = new CubicEase { EasingMode = EasingMode.EaseOut },
            FillBehavior   = FillBehavior.Stop,
        };
        anim.Completed += (_, _) =>
        {
            SettingsPanel.BeginAnimation(MaxHeightProperty, null);
            SettingsPanel.MaxHeight = target;
        };
        SettingsPanel.BeginAnimation(MaxHeightProperty, anim);
    }

    // ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ Settings panel build (once, lazily) ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬

    private void BuildSettingsPanel()
    {
        SettingsPanel.Children.Clear();
        _swatchEllipses.Clear();
        // Reset control references; only expanded sections rebuild them.
        _dropText1 = null!; _dropText2 = null!; _dropText3 = null!;
        _prayerCountryText = null!; _prayerCityText = null!; _prayerMethodText = null;
        _couchAudioText = null; _morningAudioText = null;

        double y = 8;
        void Add(UIElement el) => SettingsPanel.Children.Add(el);
        bool Exp(string key) => _sectionExpanded.TryGetValue(key, out var v) && v;
        void Header(string key, string text) { AddSectionHeader(key, text, y); y += 38; }

        // Audio
        Header("Audio", "Audio Settings");
        if (Exp("Audio"))
        {
            Add(RowLabel("Device 1", y + 7));
            var (btn1, txt1) = MakeDropButton(new Point(94, y), 1);
            _dropText1 = txt1; Add(btn1);
            y += 46;
            Add(RowLabel("Device 2", y + 7));
            var (btn2, txt2) = MakeDropButton(new Point(94, y), 2);
            _dropText2 = txt2; Add(btn2);
            y += 46;
            // Optional 3rd output — leave on "Select" for a plain 2-device toggle.
            Add(RowLabel("Device 3", y + 7));
            var (btn3, txt3) = MakeDropButton(new Point(94, y), 8);
            _dropText3 = txt3; Add(btn3);
            y += 42;
        }
        y += 6;

        // Theme
        Header("Theme", "Theme");
        if (Exp("Theme"))
        {
            BuildSwatches(y);
            y += 48;
        }
        y += 6;

        // Prayer
        Header("Prayer", "Prayer");
        if (Exp("Prayer"))
        {
            Add(RowLabel("Country", y + 7));
            var (prayerCountryBtn, prayerCountryTxt) = MakeDropButton(new Point(94, y), 3);
            _prayerCountryText = prayerCountryTxt; Add(prayerCountryBtn);
            y += 46;
            Add(RowLabel("City", y + 7));
            var (prayerCityBtn, prayerCityTxt) = MakeDropButton(new Point(94, y), 4);
            _prayerCityText = prayerCityTxt; Add(prayerCityBtn);
            y += 46;
            Add(RowLabel("Method", y + 7));
            var (prayerMethodBtn, prayerMethodTxt) = MakeDropButton(new Point(94, y), 7);
            _prayerMethodText = prayerMethodTxt; Add(prayerMethodBtn);
            y += 46;
            Add(RowLabel("Time", y + 7));
            bool use24 = AppSettings.Current.Prayer.Use24Hour;
            var tfText = new TextBlock
            {
                Text                = use24 ? "24-hour" : "12-hour",
                FontFamily          = new FontFamily("Segoe UI"),
                FontSize            = 12,
                FontWeight          = FontWeights.Bold,
                HorizontalAlignment = HorizontalAlignment.Center,
                VerticalAlignment   = VerticalAlignment.Center,
            };
            tfText.SetResourceReference(ForegroundProperty, "TextBrush");
            var tfBtn = new Border
            {
                Width        = 130,
                Height       = 30,
                CornerRadius = new CornerRadius(10),
                Cursor       = Cursors.Hand,
                Child        = tfText,
            };
            tfBtn.SetResourceReference(BackgroundProperty, "BtnBrush");
            tfBtn.MouseLeftButtonDown += (_, ev) => { ev.Handled = true; ToggleTimeFormat(); };
            Canvas.SetLeft(tfBtn, 94);
            Canvas.SetTop(tfBtn, y);
            Add(tfBtn);
            y += 42;

            // Official online times (Qatar only): fetch from the Ministry of Interior / Awqaf,
            // falling back to the offline calculation when offline or for other countries.
            BuildSliderToggleRow("Online Times (Qatar)", y, AppSettings.Current.Prayer.UseOnlineTimes,
                () => ToggleOnlineTimes()); y += 32;

            // Iqama alarm: on/off toggle + volume slider. The slider plays a short
            // preview on release so you can hear the level you picked.
            bool iqamaOn = AppSettings.Current.Prayer.PlayIqamaSound;
            BuildSliderToggleRow("Iqama Sound", y, iqamaOn, () => ToggleIqamaSound()); y += 32;

            if (iqamaOn)
            {
                Add(FieldLabel("Volume", y + 2));
                int volPct = (int)Math.Round(AppSettings.Current.Prayer.IqamaVolume * 100);
                var volLabel = new TextBlock
                {
                    Text          = $"{volPct}%",
                    FontFamily    = new FontFamily("Segoe UI"),
                    FontSize      = 12,
                    FontWeight    = FontWeights.Bold,
                    Width         = 40,
                    TextAlignment = TextAlignment.Right,
                };
                volLabel.SetResourceReference(ForegroundProperty, "TextBrush");
                Canvas.SetLeft(volLabel, 360);
                Canvas.SetTop(volLabel, y + 2);

                var volSlider = new Slider
                {
                    Minimum = 0, Maximum = 100,
                    Width = 230, Height = 22,
                    Value = volPct,
                    IsSnapToTickEnabled = true, TickFrequency = 1,
                    Style = (Style)Application.Current.Resources["ThinSlider"],
                };
                Canvas.SetLeft(volSlider, 120);
                Canvas.SetTop(volSlider, y);
                volSlider.ValueChanged += (_, ev) => volLabel.Text = $"{(int)ev.NewValue}%";
                // Persist + preview on release rather than on every drag tick.
                volSlider.PreviewMouseLeftButtonUp += (_, _) =>
                {
                    var cfg = AppSettings.Current;
                    cfg.Prayer.IqamaVolume = volSlider.Value / 100.0;
                    cfg.Save();
                    AppSettings.Invalidate();
                    ReinitPrayerModule();
                    IqamaSound.Play((float)(volSlider.Value / 100.0));
                };
                Add(volSlider);
                Add(volLabel);
                y += 38;
            }
        }
        y += 6;

        // Display
        Header("Display", "Display Settings");
        if (Exp("Display"))
        {
            var s = AppSettings.Current;
            BuildSliderToggleRow("Display Brightness Slider", y, s.BrightnessSliderEnabled,
                () => ToggleSlider("Brightness")); y += 28;
            BuildSliderToggleRow("SDR Slider", y, s.SdrSliderEnabled,
                () => ToggleSlider("Sdr")); y += 28;
            BuildSliderToggleRow("Auto HDR", y, s.AutoHdrEnabled,
                () => ToggleSlider("AutoHdr")); y += 32;
        }
        y += 6;

