    // A clickable, collapsible section header (chevron + title). Tapping toggles the
    // section and re-animates the panel height.
    private void AddSectionHeader(string key, string text, double top)
    {
        bool expanded = _sectionExpanded.TryGetValue(key, out var e) && e;

        var chevron = new TextBlock
        {
            Text              = expanded ? "v" : ">",
            FontFamily        = new FontFamily("Segoe UI"),
            FontSize          = 12,
            FontWeight        = FontWeights.Bold,
            Width             = 16,
            VerticalAlignment = VerticalAlignment.Center,
        };
        chevron.SetResourceReference(ForegroundProperty, "DimBrush");

        var label = new TextBlock
        {
            Text              = text,
            FontFamily        = new FontFamily("Segoe UI"),
            FontSize          = 13,
            FontWeight        = FontWeights.Bold,
            Margin            = new Thickness(6, 0, 0, 0),
            VerticalAlignment = VerticalAlignment.Center,
        };
        label.SetResourceReference(ForegroundProperty, "TextBrush");

        var sp = new StackPanel
        {
            Orientation       = System.Windows.Controls.Orientation.Horizontal,
            VerticalAlignment = VerticalAlignment.Center,
            Margin            = new Thickness(14, 0, 0, 0),
        };
        sp.Children.Add(chevron);
        sp.Children.Add(label);

        var btn = new Border
        {
            Width        = 388,
            Height       = 32,
            CornerRadius = new CornerRadius(9),
            Cursor       = Cursors.Hand,
            Child        = sp,
        };
        btn.SetResourceReference(BackgroundProperty, "BtnBrush");
        btn.MouseLeftButtonDown += (_, ev) => { ev.Handled = true; ToggleSection(key); };
        Canvas.SetLeft(btn, 16);
        Canvas.SetTop(btn, top);
        SettingsPanel.Children.Add(btn);
    }

    private void ToggleSection(string key)
    {
        _sectionExpanded[key] = !(_sectionExpanded.TryGetValue(key, out var v) && v);
        BuildSettingsPanel();
        PopulateDropButtons();
        UpdatePrayerBtnStates();
        AnimateSettingsHeight(_settingsContentH);
    }

    private void AnimateSettingsHeight(double target)
    {
        var anim = new DoubleAnimation
        {
            To             = target,
            Duration       = TimeSpan.FromMilliseconds(200),
            EasingFunction = new CubicEase { EasingMode = EasingMode.EaseOut },
            FillBehavior   = FillBehavior.Stop,
        };
        anim.Completed += (_, _) =>
        {
            SettingsPanel.BeginAnimation(MaxHeightProperty, null);
            SettingsPanel.MaxHeight = target;
        };
        SettingsPanel.BeginAnimation(MaxHeightProperty, anim);
    }

    // Like RowLabel but a touch wider so longer field names ("Brightness") don't clip.
    private TextBlock FieldLabel(string text, double top)
    {
        var lbl = new TextBlock
        {
            Text       = text,
            FontFamily = new FontFamily("Segoe UI"),
            FontSize   = 12,
            FontWeight = FontWeights.Bold,
            Width      = 90,
        };
        lbl.SetResourceReference(ForegroundProperty, "TextBrush");
        Canvas.SetLeft(lbl, 20);
        Canvas.SetTop(lbl, top);
        return lbl;
    }

    private static void EnsureAllCards(List<CardConfig> cards)
    {
        // New/unknown cards default to VISIBLE so a freshly-added card shows up; the user can
        // hide it in Edit mode. (Cards already in the list keep whatever Visible the user chose.)
        foreach (var id in CardHeights.Keys)
            if (!cards.Any(c => c.Id == id))
                cards.Add(new CardConfig { Id = id, Visible = true });
    }

    private void BuildSliderToggleRow(string label, double y, bool enabled, Action onClick)
    {
        var lbl = new TextBlock
        {
            Text       = label,
            FontFamily = new FontFamily("Segoe UI"),
            FontSize   = 11,
            Width      = 170,
        };
        lbl.SetResourceReference(ForegroundProperty, "DimBrush");
        Canvas.SetLeft(lbl, 40);
        Canvas.SetTop(lbl, y + 7);
        SettingsPanel.Children.Add(lbl);

        var txt = new TextBlock
        {
            Text                = enabled ? "Enabled" : "Disabled",
            FontFamily          = new FontFamily("Segoe UI"),
            FontSize            = 12,
            FontWeight          = FontWeights.Bold,
            HorizontalAlignment = HorizontalAlignment.Center,
            VerticalAlignment   = VerticalAlignment.Center,
        };
        txt.SetResourceReference(ForegroundProperty, enabled ? "GoodBrush" : "DimBrush");

        var btn = new Border
        {
            Width        = 180,
            Height       = 22,
            CornerRadius = new CornerRadius(11),
            Cursor       = Cursors.Hand,
            Child        = txt,
        };
        btn.SetResourceReference(BackgroundProperty, "BtnBrush");
        btn.MouseLeftButtonDown += (_, e) => { e.Handled = true; onClick(); };
        Canvas.SetLeft(btn, 220);
        Canvas.SetTop(btn, y + 3);
        SettingsPanel.Children.Add(btn);
    }

    private void ToggleSlider(string which)
    {
        var cfg = AppSettings.Current;
        if      (which == "Brightness") cfg.BrightnessSliderEnabled = !cfg.BrightnessSliderEnabled;
        else if (which == "Sdr")        cfg.SdrSliderEnabled        = !cfg.SdrSliderEnabled;
        else if (which == "AutoHdr")    cfg.AutoHdrEnabled          = !cfg.AutoHdrEnabled;
        cfg.Save();
        AppSettings.Invalidate();
        RefreshState();
        RefreshSettingsPanel();
    }

    private void RefreshSettingsPanel()
    {
        BuildSettingsPanel();
        PopulateDropButtons();
        UpdatePrayerBtnStates();
    }

    private TextBlock SectionLabel(string text, double top)
    {
        var lbl = new TextBlock
        {
            Text       = text,
            FontFamily = new FontFamily("Segoe UI"),
            FontSize   = 12,
            FontWeight = FontWeights.Bold,
        };
        lbl.SetResourceReference(ForegroundProperty, "DimBrush");
        Canvas.SetLeft(lbl, 20);
        Canvas.SetTop(lbl, top);
        return lbl;
    }

    private TextBlock RowLabel(string text, double top)
    {
        var lbl = new TextBlock
        {
            Text       = text,
            FontFamily = new FontFamily("Segoe UI"),
            FontSize   = 12,
            FontWeight = FontWeights.Bold,
            Width      = 68,
        };
        lbl.SetResourceReference(ForegroundProperty, "TextBrush");
        Canvas.SetLeft(lbl, 20);
        Canvas.SetTop(lbl, top);
        return lbl;
    }

    private (Border btn, TextBlock text) MakeDropButton(Point loc, int deviceNum)
    {
        var txt = new TextBlock
        {
            Text            = "Select...",
            FontFamily      = new FontFamily("Segoe UI"),
            FontSize        = 12,
            VerticalAlignment = VerticalAlignment.Center,
            TextTrimming    = TextTrimming.CharacterEllipsis,
            Margin          = new Thickness(10, 0, 24, 0),
        };
        txt.SetResourceReference(ForegroundProperty, "TextBrush");

        var chevron = new TextBlock
        {
            Text                = "v",
            FontFamily          = new FontFamily("Segoe UI"),
            FontSize            = 13,
            HorizontalAlignment = HorizontalAlignment.Right,
            VerticalAlignment   = VerticalAlignment.Center,
            Margin              = new Thickness(0, 0, 8, 0),
        };
        chevron.SetResourceReference(ForegroundProperty, "DimBrush");

        var grid = new Grid();
        grid.Children.Add(txt);
        grid.Children.Add(chevron);

        var btn = new Border
        {
            Width        = 306,
            Height       = 34,
            CornerRadius = new CornerRadius(10),
            Cursor       = Cursors.Hand,
            Child        = grid,
        };
        btn.SetResourceReference(BackgroundProperty, "BtnBrush");
        btn.MouseLeftButtonDown += (_, e) =>
        {
            e.Handled = true;
            if      (deviceNum == 3) ShowPrayerCountryDropdown(btn);
            else if (deviceNum == 4) ShowPrayerCityDropdown(btn);
            else if (deviceNum == 5) ShowCouchAudioDropdown(btn);
            else if (deviceNum == 6) ShowMorningAudioDropdown(btn);
            else if (deviceNum == 7) ShowPrayerMethodDropdown(btn);
            else                     ShowDropdown(deviceNum, btn);
        };

        Canvas.SetLeft(btn, loc.X);
        Canvas.SetTop(btn,  loc.Y);
        return (btn, txt);
    }

    private void BuildSwatches(double top)
    {
        string current  = AppSettings.Current.Theme;
        int swatchSize  = 38, gap = 10;
        int totalW      = Themes.Count * swatchSize + (Themes.Count - 1) * gap;
        int sx          = (420 - totalW) / 2;

        foreach (var (name, pal) in Themes)
        {
            bool selected = name == current;

            var outerEl = new Ellipse
            {
                Fill            = new SolidColorBrush(selected ? Colors.White : pal.Card),
                Stroke          = new SolidColorBrush(Color.FromArgb(160, 90, 90, 90)),
                StrokeThickness = 2.0,
            };
            var innerEl = new Ellipse
            {
                Fill       = new SolidColorBrush(pal.Card),
                Margin     = new Thickness(3),
                Visibility = selected ? Visibility.Visible : Visibility.Collapsed,
            };

            var grid = new Grid { Width = swatchSize, Height = swatchSize, Cursor = Cursors.Hand, Tag = name };
            grid.Children.Add(outerEl);
            grid.Children.Add(innerEl);
            grid.MouseLeftButtonDown += OnSwatchClick;

            _swatchEllipses[name] = (outerEl, innerEl);
            Canvas.SetLeft(grid, sx);
            Canvas.SetTop(grid,  top);
            SettingsPanel.Children.Add(grid);
            sx += swatchSize + gap;
        }
    }

    // ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ Prayer country selection ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬

    private void UpdatePrayerBtnStates()
    {
        if (_prayerCountryText is null) return;
        var cfg = AppSettings.Current.Prayer;
        _prayerCountryText.Text = string.IsNullOrEmpty(cfg.Country) ? "Select" : cfg.Country;

        if (_prayerCityText is null) return;
        if (string.IsNullOrEmpty(cfg.City))
        {
            _prayerCityText.Text = "Select";
        }
        else
        {
            var preset = PrayerCountryPresets.FindByCity(cfg.Country, cfg.City)
                      ?? PrayerCountryPresets.ForCountry(cfg.Country).FirstOrDefault();
            _prayerCityText.Text = preset is not null ? PrayerCountryPresets.CityLabel(preset) : cfg.City;
        }

        if (_prayerMethodText is not null)
            _prayerMethodText.Text = PrayerCalcMethods.NameFor(cfg.CalcMethod);
    }

    private void ShowPrayerCountryDropdown(Border anchor)
    {
        // Index 0 = "Select" (none) so the location can be left unset / reset.
        var names   = new List<string> { "Select" };
        names.AddRange(PrayerCountryPresets.Countries);
        var current = AppSettings.Current.Prayer.Country;
        int found   = PrayerCountryPresets.Countries.ToList().IndexOf(current);
        int selIdx  = found < 0 ? 0 : found + 1;

        var screenPt = anchor.PointToScreen(new Point(0, anchor.ActualHeight + 2));
        var drop = new DropdownWindow(names, selIdx, screenPt, (int)anchor.ActualWidth)
        {
            Owner = this,
        };

        _actionInProgress = true;
        drop.Selected += idx =>
        {
            if (idx <= 0) OnPrayerLocationClear();   // also clears City (it depends on Country)
            else          OnPrayerCountrySelect(names[idx]);
        };
        drop.Closed   += (_, _) => _actionInProgress = false;
        drop.Show();
    }

    private void ShowPrayerCityDropdown(Border anchor)
    {
        var country = AppSettings.Current.Prayer.Country;
        var presets = PrayerCountryPresets.ForCountry(country);
        if (presets.Count == 0) return;

        // Index 0 = "Select" (none); real cities follow at +1.
        var labels = new List<string> { "Select" };
        labels.AddRange(presets.Select(PrayerCountryPresets.CityLabel));
        int found  = presets.ToList().FindIndex(p => p.City == AppSettings.Current.Prayer.City);
        int selIdx = found < 0 ? 0 : found + 1;

        var screenPt = anchor.PointToScreen(new Point(0, anchor.ActualHeight + 2));
        var drop = new DropdownWindow(labels, selIdx, screenPt, (int)anchor.ActualWidth)
        {
            Owner = this,
        };

        _actionInProgress = true;
        drop.Selected += idx =>
        {
            if (idx <= 0) OnPrayerCityClear();
            else          OnPrayerCitySelect(presets[idx - 1]);
        };
        drop.Closed   += (_, _) => _actionInProgress = false;
        drop.Show();
    }

    private void ShowPrayerMethodDropdown(Border anchor)
    {
        var names  = PrayerCalcMethods.All.Select(m => m.Name).ToList();
        int selIdx = PrayerCalcMethods.IndexOf(AppSettings.Current.Prayer.CalcMethod);

        var screenPt = anchor.PointToScreen(new Point(0, anchor.ActualHeight + 2));
        var drop = new DropdownWindow(names, selIdx, screenPt, (int)anchor.ActualWidth)
        {
            Owner = this,
        };

        _actionInProgress = true;
        drop.Selected += idx => OnPrayerMethodSelect(PrayerCalcMethods.All[idx].Key);
        drop.Closed   += (_, _) => _actionInProgress = false;
        drop.Show();
    }

    private void OnPrayerMethodSelect(string methodKey)
    {
        var cfg = AppSettings.Current;
        if (cfg.Prayer.CalcMethod == methodKey) { UpdatePrayerBtnStates(); return; }

        cfg.Prayer.CalcMethod = methodKey;
        cfg.Save();
        AppSettings.Invalidate();
        UpdatePrayerBtnStates();
        ReinitPrayerModule();
    }

    private void ToggleTimeFormat()
    {
        var cfg = AppSettings.Current;
        cfg.Prayer.Use24Hour = !cfg.Prayer.Use24Hour;
        cfg.Save();
        AppSettings.Invalidate();
        ReinitPrayerModule();
        RefreshSettingsPanel();
    }

    // Toggles fetching official online prayer times (Qatar). Off → always use the offline
    // calculation. Reinit picks the source up immediately.
    private void ToggleOnlineTimes()
    {
        var cfg = AppSettings.Current;
        cfg.Prayer.UseOnlineTimes = !cfg.Prayer.UseOnlineTimes;
        cfg.Save();
        AppSettings.Invalidate();
        ReinitPrayerModule();
        RefreshSettingsPanel();
    }

    // Toggles the iqama alarm sound. Reinit picks the change up immediately.
    private void ToggleIqamaSound()
    {
        var cfg = AppSettings.Current;
        cfg.Prayer.PlayIqamaSound = !cfg.Prayer.PlayIqamaSound;
        cfg.Save();
        AppSettings.Invalidate();
        ReinitPrayerModule();
        RefreshSettingsPanel();
    }

    private void OnPrayerCountrySelect(string countryName)
    {
        var cfg = AppSettings.Current;
        if (cfg.Prayer.Country == countryName) { UpdatePrayerBtnStates(); return; }

        var presets = PrayerCountryPresets.ForCountry(countryName);
        if (presets.Count == 0) return;

        PrayerCountryPresets.Apply(presets[0], cfg.Prayer);
        cfg.Save();
        AppSettings.Invalidate();
        UpdatePrayerBtnStates();
        ReinitPrayerModule();
    }

    private void OnPrayerCitySelect(PrayerCountryPresets.LocationPreset preset)
    {
        var cfg = AppSettings.Current;
        if (cfg.Prayer.Country == preset.Country && cfg.Prayer.City == preset.City) return;

        PrayerCountryPresets.Apply(preset, cfg.Prayer);
        cfg.Save();
        AppSettings.Invalidate();
        UpdatePrayerBtnStates();
        ReinitPrayerModule();
    }

    // Reset the prayer location to unset ("Select"). Clears both Country and City since the
    // city list depends on the country; the card then shows its "Set up in Settings" state.
    private void OnPrayerLocationClear()
    {
        var cfg = AppSettings.Current;
        cfg.Prayer.Country = "";
        cfg.Prayer.City    = "";
        cfg.Save();
        AppSettings.Invalidate();
        UpdatePrayerBtnStates();
        ReinitPrayerModule();
    }

    private void OnPrayerCityClear()
    {
        var cfg = AppSettings.Current;
        cfg.Prayer.City = "";
        cfg.Save();
        AppSettings.Invalidate();
        UpdatePrayerBtnStates();
        ReinitPrayerModule();
    }

    private void ReinitPrayerModule()
    {
        try
        {
            _prayerModule?.Dispose();
            _prayerModule = null;

            // Country/City unset → show the setup hint instead of calculating.
            var p = AppSettings.Current.Prayer;
            if (string.IsNullOrEmpty(p.Country) || string.IsNullOrEmpty(p.City))
            {
                PrayerStatus.SetResourceReference(TextBlock.ForegroundProperty, "DimBrush");
                PrayerStatus.Text          = "Set up in Settings";
                PrayerCountdown.Text       = "";
                PrayerCountdown.Visibility = Visibility.Collapsed;
                _latestPrayerStatus        = "Set up in Settings";
                _latestPrayerCountdown     = "";
                WritePrayerStatusJson();
                return;
            }

            PrayerStatus.SetResourceReference(TextBlock.ForegroundProperty, "AmberBrush");
            PrayerStatus.Text          = "Loading...";
            PrayerCountdown.Text       = "";
            PrayerCountdown.Visibility = Visibility.Collapsed;
            _latestPrayerStatus        = "Loading...";
            _latestPrayerCountdown     = "";
            WritePrayerStatusJson();
            _prayerModule = new PrayerTimesModule(AppSettings.Current.Prayer);
            _prayerModule.Updated += (status, countdown) =>
            {
                _latestPrayerStatus    = status;
                _latestPrayerCountdown = countdown;
                PrayerStatus.Text        = status;
                PrayerCountdown.Text     = countdown;
                PrayerCountdown.Visibility = string.IsNullOrEmpty(countdown)
                    ? Visibility.Collapsed : Visibility.Visible;
                WritePrayerStatusJson();
            };
            _ = _prayerModule.InitializeAsync();
        }
        catch (Exception ex) { Logger.Log($"ReinitPrayer: {ex.Message}"); }
    }

    // ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ Audio device dropdown ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬

    private void PopulateDropButtons()
    {
        _devices = AudioManager.GetRenderDevices();
        var s = AppSettings.Current;

        // Keep a saved-but-currently-absent device (e.g. unplugged) selectable so closing
        // Settings doesn't silently clear it just because it's not enumerated right now.
        EnsureDeviceListed(s.Device1Id, s.Device1Label);
        EnsureDeviceListed(s.Device2Id, s.Device2Label);
        EnsureDeviceListed(s.Device3Id, s.Device3Label);

        _sel1 = _devices.FindIndex(d => d.Id == s.Device1Id);
        _sel2 = _devices.FindIndex(d => d.Id == s.Device2Id);
        _sel3 = _devices.FindIndex(d => d.Id == s.Device3Id);

        // No auto-select: an unset slot stays on "Select" so the Audio card shows its
        // "Set up in Settings" state until the user actually picks two devices.
        // Audio section may be collapsed (controls not built) — guard the refs.
        if (_dropText1 is not null) _dropText1.Text = _sel1 >= 0 ? _devices[_sel1].Name : "Select...";
        if (_dropText2 is not null) _dropText2.Text = _sel2 >= 0 ? _devices[_sel2].Name : "Select...";
        if (_dropText3 is not null) _dropText3.Text = _sel3 >= 0 ? _devices[_sel3].Name : "Select...";
    }

    private void EnsureDeviceListed(string id, string label)
    {
        if (!string.IsNullOrEmpty(id) && !_devices.Any(d => d.Id == id))
            _devices.Add((id, string.IsNullOrEmpty(label) ? id : label));
    }

    private void ShowDropdown(int deviceNum, Border anchor)
    {
        if (_devices.Count == 0) return;

        // deviceNum 8 = the optional 3rd audio slot (1/2 are the first two).
        int currentSel = deviceNum == 1 ? _sel1 : deviceNum == 2 ? _sel2 : _sel3;
        // Index 0 is a "Select" (none) entry so the user can leave a slot unconfigured or
        // reset it back; real devices follow at +1.
        var names      = new List<string> { "Select" };
        names.AddRange(_devices.Select(d => d.Name));
        int displaySel = currentSel < 0 ? 0 : currentSel + 1;
        var screenPt   = anchor.PointToScreen(new Point(0, anchor.ActualHeight + 2));

        var drop = new DropdownWindow(names, displaySel, screenPt, (int)anchor.ActualWidth)
        {
            Owner = this,
        };

        _actionInProgress = true;
        drop.Selected += idx =>
        {
            int real = idx <= 0 ? -1 : idx - 1;   // 0 = "Select" (none)
            if (deviceNum == 1) _sel1 = real; else if (deviceNum == 2) _sel2 = real; else _sel3 = real;
            if (_dropText1 is not null) _dropText1.Text = _sel1 >= 0 ? _devices[_sel1].Name : "Select...";
            if (_dropText2 is not null) _dropText2.Text = _sel2 >= 0 ? _devices[_sel2].Name : "Select...";
            if (_dropText3 is not null) _dropText3.Text = _sel3 >= 0 ? _devices[_sel3].Name : "Select...";
        };
        drop.Closed += (_, _) => _actionInProgress = false;
        drop.Show();
    }

    // ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ Save settings ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬

    // Returns false (and shows error) if validation fails, so the panel stays open.
    private bool TrySaveSettings()
    {
        // (unset slots are saved as cleared below — no early return) // nothing selected yet ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â just close
        // Two REAL devices that are identical is invalid; everything else — including one or
        // both left on "Select" — is allowed and saved so the Audio card shows its setup state.
        // No two REAL selected slots may be the same device. Any slot left on "Select" is fine.
        if ((_sel1 >= 0 && _sel2 >= 0 && _sel1 == _sel2) ||
            (_sel1 >= 0 && _sel3 >= 0 && _sel1 == _sel3) ||
            (_sel2 >= 0 && _sel3 >= 0 && _sel2 == _sel3))
        {
            MessageBox.Show("Each audio device must be different.", "PC Companion",
                MessageBoxButton.OK, MessageBoxImage.Warning);
            return false;
        }

        var cur = AppSettings.Current;
        cur.Device1Id    = _sel1 >= 0 ? _devices[_sel1].Id   : "";
        cur.Device1Label = _sel1 >= 0 ? _devices[_sel1].Name : "";
        cur.Device2Id    = _sel2 >= 0 ? _devices[_sel2].Id   : "";
        cur.Device2Label = _sel2 >= 0 ? _devices[_sel2].Name : "";
        cur.Device3Id    = _sel3 >= 0 ? _devices[_sel3].Id   : "";
        cur.Device3Label = _sel3 >= 0 ? _devices[_sel3].Name : "";
        cur.Save();
        AppSettings.Invalidate();
        RefreshState();
        return true;
    }

