ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬

    private void OnSwatchClick(object sender, MouseButtonEventArgs e)
    {
        e.Handled = true;
        if (sender is not FrameworkElement el || el.Tag is not string name) return;
        if (!Themes.TryGetValue(name, out var t)) return;

        var s = AppSettings.Current;
        s.Theme = name;
        s.Save();
        AppSettings.Invalidate();

        ApplyThemePalette(t);
        UpdateSwatchSelection(name);

        // AllowsTransparency windows can leave stale dirty regions when brushes change.
        // UpdateLayout forces a synchronous layout+render pass that clears them.
        UpdateLayout();

        // DropShadowEffect caches a bitmap of the element. Replacing resource brushes
        // doesn't invalidate that cache for TextBlocks whose Foreground was explicitly
        // assigned by RefreshState(). Force a re-render on the next frame.
        Dispatcher.BeginInvoke(DispatcherPriority.Render, ForceStatusRedraw);
    }

    private void ForceStatusRedraw()
    {
        var res = Application.Current.Resources;
        static DropShadowEffect NewShadow() =>
            new() { Color = Colors.Black, ShadowDepth = 0, BlurRadius = 0, Opacity = 0.7 };

        bool gopherOn = GopherStatus.Text == "ON";
        GopherStatus.Foreground = gopherOn ? (Brush)res["GoodBrush"] : (Brush)res["BadBrush"];
        GopherStatus.Effect     = NewShadow();

        var cfg = AppSettings.Current;
        bool audioConfigured = !string.IsNullOrEmpty(cfg.Device1Id) && !string.IsNullOrEmpty(cfg.Device2Id);
        AudioStatus.Foreground = !audioConfigured
            ? (Brush)res["DimBrush"]
            : AudioStatus.Text == Short(cfg.Device1Label)
                ? (Brush)res["PurpBrush"]
                : (Brush)res["BlueBrush"];
        AudioStatus.Effect = NewShadow();

        HdrStatus.Foreground = HdrStatus.Text switch
        {
            "ON"  => (Brush)res["GoodBrush"],
            "OFF" => (Brush)res["BadBrush"],
            _       => (Brush)res["DimBrush"],
        };
        HdrStatus.Effect = NewShadow();

        AutoHdrStatus.Foreground = AutoHdrStatus.Text switch
        {
            "ON"  => (Brush)res["GoodBrush"],
            "OFF" => (Brush)res["BadBrush"],
            _       => (Brush)res["DimBrush"],
        };
        AutoHdrStatus.Effect = NewShadow();

        CouchModeStatus.Foreground = CouchModeStatus.Text == "ON"
            ? (Brush)res["GoodBrush"] : (Brush)res["BadBrush"];
        CouchModeStatus.Effect = NewShadow();

        MorningModeStatus.Foreground = MorningModeStatus.Text == "ON"
            ? (Brush)res["GoodBrush"] : (Brush)res["BadBrush"];
        MorningModeStatus.Effect = NewShadow();

        // These two keep their DynamicResource Foreground binding (never explicitly assigned
        // in code); only the effect cache needs forcing.
        PrayerStatus.Effect    = NewShadow();
        PrayerCountdown.Effect = NewShadow();
    }

    private static void ApplyThemePalette((Color Bg, Color Card, Color Btn, Color Dim, Color Text, Color Good, Color Bad, Color Stroke) t)
    {
        var res = Application.Current.Resources;
        res["BgBrush"]     = new SolidColorBrush(t.Bg);
        res["CardBrush"]   = new SolidColorBrush(t.Card);
        res["BtnBrush"]    = new SolidColorBrush(t.Btn);
        res["DimBrush"]    = new SolidColorBrush(t.Dim);
        res["TextBrush"]   = new SolidColorBrush(t.Text);
        res["GoodBrush"]   = new SolidColorBrush(t.Good);
        res["BadBrush"]    = new SolidColorBrush(t.Bad);
        res["StrokeBrush"] = new SolidColorBrush(t.Stroke);

        // Accent colors: light themes need darker variants to stay readable on near-white backgrounds.
        bool light = t.Stroke.A > 0;
        res["PurpBrush"]  = new SolidColorBrush(light ? H("#6B2FCC") : H("#C49AFF"));
        res["BlueBrush"]  = new SolidColorBrush(light ? H("#0075B2") : H("#75D8FF"));
        res["AmberBrush"] = new SolidColorBrush(light ? H("#8A5C00") : H("#FFD580"));
    }

    private void UpdateSwatchSelection(string selectedName)
    {
        foreach (var (name, (outer, inner)) in _swatchEllipses)
        {
            if (!Themes.TryGetValue(name, out var pal)) continue;
            bool sel        = name == selectedName;
            outer.Fill      = new SolidColorBrush(sel ? Colors.White : pal.Card);
            inner.Visibility = sel ? Visibility.Visible : Visibility.Collapsed;
        }
    }

