    private const string HelpGopher =
        "Gopher360 lets your controller act like a mouse/keyboard. " +
        "Controls and cursor speed depend on the Gopher360 config.ini/settings. " +
        "If controls feel too fast/slow, adjust the Gopher360 configuration. " +
        "For advanced help, check the Gopher360 GitHub page.";

    private const string HelpAudio =
        "Cycles the Windows default playback device through your configured outputs (two, or " +
        "three if you set the optional Device 3 in Settings). " +
        "If switching stops working, the device name may have changed after a driver update, " +
        "reconnect, or Windows audio device rename. Re-select the devices in settings.";

    private const string HelpHdr =
        "Controls HDR/display-related features. " +
        "Display Brightness uses monitor control/DDC-CI where supported. " +
        "If brightness control does not work, enable DDC/CI in the monitor menu, turn Eco Mode off, " +
        "and try disabling G-Sync/FreeSync/VRR or ELMB/ULMB/motion-blur reduction. " +
        "Some docks/adapters may block DDC/CI. " +
        "SDR Balance is app-controlled and may not exactly mirror the Windows Settings slider.";

    private const string HelpPrayer =
        "Shows the next prayer. It counts down to the adhan (call to prayer) first; once the " +
        "adhan passes it counts down to that prayer's iqama. " +
        "For Qatar, official times are fetched online (Ministry of Awqaf) when available, " +
        "otherwise they're calculated offline. Iqama = adhan + your per-prayer offsets. " +
        "Adjust offsets to match your local mosque or timetable.";

    private void AttachHelpEvents()
    {
        AttachHelp(GopherHelp, HelpGopher);
        AttachHelp(AudioHelp,  HelpAudio);
        AttachHelp(HdrHelp,    HelpHdr);
        AttachHelp(PrayerHelp, HelpPrayer);

        HelpPopupBorder.MouseEnter += (_, _) => _helpHideTimer?.Stop();
        HelpPopupBorder.MouseLeave += (_, _) => StartHelpHideDelay();
    }

    private void AttachHelp(Border helpBtn, string text)
    {
        helpBtn.MouseEnter += (_, _) =>
        {
            _helpHideTimer?.Stop();
            ShowHelp(helpBtn, text);
        };
        helpBtn.MouseLeave    += (_, _) => StartHelpHideDelay();
        helpBtn.MouseLeftButtonDown += (_, e) => e.Handled = true; // block card toggle
    }

    private void ShowHelp(Border helpBtn, string text)
    {
        HelpPopupText.Text       = text;
        HelpPopup.PlacementTarget = helpBtn;
        HelpPopup.IsOpen          = true;
    }

    private void HideHelp()
    {
        _helpHideTimer?.Stop();
        _helpHideTimer  = null;
        HelpPopup.IsOpen = false;
    }

    private void StartHelpHideDelay()
    {
        _helpHideTimer?.Stop();
        _helpHideTimer = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(250) };
        _helpHideTimer.Tick += (_, _) =>
        {
            _helpHideTimer?.Stop();
            _helpHideTimer  = null;
            HelpPopup.IsOpen = false;
        };
        _helpHideTimer.Start();
    }

    protected override void OnPreviewKeyDown(System.Windows.Input.KeyEventArgs e)
    {
        base.OnPreviewKeyDown(e);
        if (e.Key == Key.Escape && HelpPopup.IsOpen)
        {
            HideHelp();
            e.Handled = true;
        }
    }

    // ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ Edit mode ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬

    private void OnEditModeToggle(object sender, MouseButtonEventArgs e)
    {
        e.Handled = true;
        if (_editMode) ExitEditMode();
        else           EnterEditMode();
    }

    private void EnterEditMode()
    {
        _editMode = true;
        EditModeText.SetResourceReference(TextBlock.ForegroundProperty, "TextBrush");
        EditModeText.Text = "Done";
        HideHelp();

        // ? buttons are irrelevant and distracting in edit mode
        foreach (var hb in new[] { GopherHelp, AudioHelp, HdrHelp, PrayerHelp })
            hb.Visibility = Visibility.Collapsed;

        LayoutCardsForEdit();    // show ALL cards (including hidden ones, to allow restoring)
        SetActionBtnOpacity(0.25);
        BuildEditOverlays();
    }

    private void ExitEditMode()
    {
        _editMode = false;
        EditModeText.SetResourceReference(TextBlock.ForegroundProperty, "TextBrush");
        EditModeText.Text = "Edit";

        foreach (var hb in new[] { GopherHelp, AudioHelp, HdrHelp, PrayerHelp })
            hb.Visibility = Visibility.Visible;

        RemoveEditOverlays();
        SetActionBtnOpacity(1.0);
        LayoutCards();  // restore proper layout ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â collapses hidden cards
    }

    // Shows ALL cards (visible and hidden) for editing, in list order
    private void LayoutCardsForEdit()
    {
        var cards = AppSettings.Current.Cards;
        EnsureAllCards(cards);

        int y = CardsTop;
        foreach (var c in cards)
        {
            if (!_cardBorders.TryGetValue(c.Id, out var border)) continue;
            border.Visibility = Visibility.Visible;
            Canvas.SetTop(border, y);
            int h = c.Id == "Display" ? (int)DisplayCard.Height : CardHeights[c.Id];
            y += h + 18;
        }
        // Hide the scene buttons while reordering cards ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â they aren't part of the layout grid.
        CouchModeBtn.Visibility   = Visibility.Collapsed;
        MorningModeBtn.Visibility = Visibility.Collapsed;
        Canvas.SetTop(SettingsToggleBtn, y);
        CardsCanvas.Height = y + 32;
    }

    // Where the +/ÃƒÆ’Ã‚Â¢Ãƒâ€¹Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ badge sits ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â same coordinates as each card's ? button
    private static (double X, double Y) EditBadgePos(string cardId) => cardId switch
    {
        "Gopher"  => (240, 22),
        "Audio"   => (240, 22),
        "Display" => (240, 15),
        "Prayer"  => (150, 27),
        _         => (240, 22),
    };

    private void BuildEditOverlays()
    {
        var cards = AppSettings.Current.Cards;
        EnsureAllCards(cards);

        foreach (var card in cards)
        {
            if (!_cardBorders.TryGetValue(card.Id, out var cardBorder)) continue;
            var inner = (Canvas)cardBorder.Child;

            if (card.Visible)
            {
                inner.Children.Add(MakeDragHandle(card.Id));

                var (bx, by) = EditBadgePos(card.Id);
                var minus = MakeEditCircleBtn("-", card.Id);
                Canvas.SetLeft(minus, bx);
                Canvas.SetTop(minus, by);
                inner.Children.Add(minus);
            }
            else
            {
                // Dim every non-overlay child individually so the (+) stays at full opacity
                foreach (var child in inner.Children.OfType<FrameworkElement>())
                    if (child.Tag is not "EditOverlay")
                        child.Opacity = 0.32;

                var (bx, by) = EditBadgePos(card.Id);
                var plus = MakeEditCircleBtn("+", card.Id);
                Canvas.SetLeft(plus, bx);
                Canvas.SetTop(plus, by);
                inner.Children.Add(plus);
            }
        }
    }

    private void RemoveEditOverlays()
    {
        foreach (var (_, cb) in _cardBorders)
        {
            if (cb.Child is not Canvas inner) continue;

            // Restore opacity on any children that were dimmed for hidden-card preview
            foreach (var child in inner.Children.OfType<FrameworkElement>())
                if (child.Tag is not "EditOverlay")
                    child.Opacity = 1.0;

            // Remove the edit overlays themselves
            inner.Children
                .OfType<FrameworkElement>()
                .Where(fe => fe.Tag is "EditOverlay")
                .ToList()
                .ForEach(el => inner.Children.Remove(el));
        }
    }

    // Called by (ÃƒÆ’Ã‚Â¢Ãƒâ€¹Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢) and (+) buttons ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â toggles card.Visible, saves, refreshes overlays
    private void OnEditToggleVisibility(string cardId)
    {
        var cfg  = AppSettings.Current;
        var card = cfg.Cards.FirstOrDefault(c => c.Id == cardId);
        if (card is null) return;
        card.Visible = !card.Visible;
        cfg.Save();
        AppSettings.Invalidate();

        RemoveEditOverlays();
        SetActionBtnOpacity(0.25);
        BuildEditOverlays();
    }

    // ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ iOS-style reorder helpers ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬

    private double CardH(string id) =>
        id == "Display" ? DisplayCard.Height : CardHeights[id];

    // Walks the given order and returns each card's top-of-slot Y coordinate
    private Dictionary<string, double> ComputeSlotYs(List<string> order)
    {
        var result = new Dictionary<string, double>(order.Count);
        double y = CardsTop;
        foreach (var id in order)
        {
            result[id] = y;
            y += CardH(id) + 18;
        }
        return result;
    }

    private static void AnimateCardTop(Border card, double targetY)
    {
        var anim = new DoubleAnimation
        {
            To             = targetY,
            Duration       = TimeSpan.FromMilliseconds(170),
            EasingFunction = new CubicEase { EasingMode = EasingMode.EaseOut },
        };
        card.BeginAnimation(Canvas.TopProperty, anim);
    }

    // Called on each MouseMove during drag ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â checks whether the dragged card's
    // center has crossed another card's midpoint, and if so reorders + animates.
    private void UpdateDragOrder(double draggedTop)
    {
        if (_dragCardId is null || _dragOrder is null) return;

        double draggedCenter = draggedTop + CardH(_dragCardId) / 2.0;

        // Compute slot centers as if the dragged card were not in the list
        int newIdx = 0;
        double y = CardsTop;
        foreach (var id in _dragOrder)
        {
            if (id == _dragCardId) continue;
            double h = CardH(id);
            if (draggedCenter > y + h / 2.0) newIdx++;
            y += h + 18;
        }

        int currentIdx = _dragOrder.IndexOf(_dragCardId);
        if (newIdx == currentIdx) return;

        _dragOrder.RemoveAt(currentIdx);
        _dragOrder.Insert(newIdx, _dragCardId);

        // Animate all non-dragged cards to their new slot positions
        var slotYs = ComputeSlotYs(_dragOrder);
        foreach (var (id, slotY) in slotYs)
        {
            if (id == _dragCardId) continue;
            if (!_cardBorders.TryGetValue(id, out var cb)) continue;
            AnimateCardTop(cb, slotY);
        }
    }

    // Mouse release: animate dragged card into its final slot, then commit
    private void FinishDrag()
    {
        if (_dragCard is null || _dragCardId is null || _dragOrder is null)
        { ClearDragState(); return; }

        double finalY = ComputeSlotYs(_dragOrder)[_dragCardId];

        var anim = new DoubleAnimation
        {
            To             = finalY,
            Duration       = TimeSpan.FromMilliseconds(170),
            EasingFunction = new CubicEase { EasingMode = EasingMode.EaseOut },
        };
        anim.Completed += (_, _) => CommitDrag();
        _dragCard.BeginAnimation(Canvas.TopProperty, anim);
    }

    private void CommitDrag()
    {
        if (_dragOrder is null) { ClearDragState(); return; }

        // Clear any in-flight animations and lock final Canvas.Top values
        var slotYs = ComputeSlotYs(_dragOrder);
        foreach (var (id, ty) in slotYs)
        {
            if (!_cardBorders.TryGetValue(id, out var cb)) continue;
            cb.BeginAnimation(Canvas.TopProperty, null);
            Canvas.SetTop(cb, ty);
        }

        // Write the new order to settings
        var cfg   = AppSettings.Current;
        var cards = cfg.Cards;
        EnsureAllCards(cards);
        var reordered = _dragOrder
            .Select(id => cards.First(c => c.Id == id))
            .ToList();
        cards.Clear();
        cards.AddRange(reordered);
        cfg.Save();
        AppSettings.Invalidate();

        ClearDragState();
    }

    private void ClearDragState()
    {
        if (_dragCard is not null)
        {
            _dragCard.Effect          = null;
            _dragCard.RenderTransform = null;
        }
        _dragCard   = null;
        _dragCardId = null;
        _dragOrder  = null;
    }

    private void SetActionBtnOpacity(double opacity)
    {
        if (GopherBtn.Parent is Border gb) gb.Opacity = opacity;
        if (AudioBtn.Parent  is Border ab) ab.Opacity = opacity;
        if (HdrBtn.Parent    is Border hb) hb.Opacity = opacity;
        AutoHdrBtnBorder.Opacity = opacity;
    }

    private Border MakeDragHandle(string cardId)
    {
        // Apple-style pill: small rounded bar centered at top of card
        var pill = new Border
        {
            Width            = 40,
            Height           = 5,
            CornerRadius     = new CornerRadius(2.5),
            HorizontalAlignment = HorizontalAlignment.Center,
            VerticalAlignment   = VerticalAlignment.Top,
            IsHitTestVisible = false,
        };
        pill.SetResourceReference(Border.BackgroundProperty, "DimBrush");

        // Wider transparent hit-area around the pill so it's easy to grab
        var handle = new Border
        {
            Width      = 384,
            Height     = 16,
            Tag        = "EditOverlay",
            Cursor     = Cursors.SizeNS,
            Background = System.Windows.Media.Brushes.Transparent,
            Child      = pill,
        };
        Canvas.SetLeft(handle, 0);
        Canvas.SetTop(handle, 2);

        handle.MouseLeftButtonDown += (_, e) =>
        {
            e.Handled = true;
            if (!_cardBorders.TryGetValue(cardId, out var cb)) return;

            _dragCard    = cb;
            _dragCardId  = cardId;
            _dragOffsetY = e.GetPosition(CardsCanvas).Y - Canvas.GetTop(cb);
            _dragOrder = AppSettings.Current.Cards
                .Where(c => _cardBorders.ContainsKey(c.Id))
                .Select(c => c.Id)
                .ToList();

            // Bring the dragged card to the top of the z-order so it overlays others
            CardsCanvas.Children.Remove(cb);
            CardsCanvas.Children.Add(cb);

            // Subtle lift: shadow + slight scale
            cb.RenderTransformOrigin = new Point(0.5, 0.5);
            cb.RenderTransform       = new ScaleTransform(1.02, 1.02);
            cb.Effect = new DropShadowEffect
            {
                Color       = Colors.Black,
                BlurRadius  = 14,
                ShadowDepth = 3,
                Opacity     = 0.45,
            };

            handle.CaptureMouse();
        };

        handle.MouseMove += (_, e) =>
        {
            if (!handle.IsMouseCaptured || _dragCard is null) return;
            double newTop = Math.Max(0, e.GetPosition(CardsCanvas).Y - _dragOffsetY);
            _dragCard.BeginAnimation(Canvas.TopProperty, null);  // stop any in-flight anim
            Canvas.SetTop(_dragCard, newTop);
            UpdateDragOrder(newTop);
        };

        handle.MouseLeftButtonUp += (_, e) =>
        {
            if (!handle.IsMouseCaptured) return;
            handle.ReleaseMouseCapture();
            FinishDrag();
        };

        return handle;
    }

    private Border MakeEditCircleBtn(string symbol, string cardId)
    {
        bool isPlus = symbol == "+";

        // Build the glyph from rounded Border shapes for crisp thickness at small size
        var horiz = new Border
        {
            Width = 12, Height = 3, CornerRadius = new CornerRadius(1.5),
            HorizontalAlignment = HorizontalAlignment.Center,
            VerticalAlignment   = VerticalAlignment.Center,
        };
        horiz.Background = System.Windows.Media.Brushes.Black;

        var glyph = new Grid { IsHitTestVisible = false };
        glyph.Children.Add(horiz);

        if (isPlus)
        {
            var vert = new Border
            {
                Width = 3, Height = 12, CornerRadius = new CornerRadius(1.5),
                HorizontalAlignment = HorizontalAlignment.Center,
                VerticalAlignment   = VerticalAlignment.Center,
            };
            vert.Background = System.Windows.Media.Brushes.Black;
            glyph.Children.Add(vert);
        }

        var btn = new Border
        {
            Width        = 26,
            Height       = 26,
            CornerRadius = new CornerRadius(13),
            Cursor       = Cursors.Hand,
            Tag          = "EditOverlay",
            Child        = glyph,
        };
        btn.SetResourceReference(Border.BackgroundProperty, isPlus ? "GoodBrush" : "BadBrush");
        btn.MouseLeftButtonDown += (_, e) =>
        {
            e.Handled = true;
            OnEditToggleVisibility(cardId);
        };
        return btn;
    }

